export const BODY = {"level-5":{"id":"level-5","kind":"level","level":5,"src":"level:5","title":"Level 5 · Point and Per Cent","body":"Long multiplication, which sum comes first, primes, squares and cubes, decimals and percentages, sales and profit, area and angles on a line, and the mean.","more":"Its lands: Long sums, in order · Tests, primes and powers · Fractions, decimals, per cents · Sales and profit · Area and angles · Averages and working back · Counting with care.","where":"Level 5 · maths age 10","route":"#/journey/5","cta":"See the road"},"land-l5-muldiv":{"id":"land-l5-muldiv","kind":"land","level":5,"src":"land:l5-muldiv","title":"Long sums, in order — in The Number Library","body":"6 stops on this stretch of the road: Long multiplication · Which sum first? · Problems in steps · Dividing by 9, digit by digit · Dividing near a base · Recurring decimals by one more.","art":"art/w-library.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Number Library · Level 5","route":"#/world/library","cta":"Visit Library"},"land-l5-powers":{"id":"land-l5-powers","kind":"land","level":5,"src":"land:l5-powers","title":"Tests, primes and powers — in The Square Palace","body":"5 stops on this stretch of the road: Tests for 4 and 8 · Is it prime? · Squaring numbers that end in 5 · What a square number is · Powers: the little number.","art":"art/w-palace.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Square Palace · Level 5","route":"#/world/palace","cta":"Visit Palace"},"land-l5-decimals":{"id":"land-l5-decimals","kind":"land","level":5,"src":"land:l5-decimals","title":"Fractions, decimals, per cents — in The Decimal Dock","body":"6 stops on this stretch of the road: Same share, different pieces · Which slice is bigger? · Line up the point · Rounding decimals · Fractions, decimals, per cents · Percentages of an amount.","art":"art/w-dock.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Decimal Dock · Level 5","route":"#/world/dock","cta":"Visit Dock"},"land-l5-money":{"id":"land-l5-money","kind":"land","level":5,"src":"land:l5-money","title":"Sales and profit — in Coin Street","body":"3 stops on this stretch of the road: The best buy · A sale · Profit and loss.","art":"art/w-coinstreet.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"Coin Street · Level 5","route":"#/world/coinstreet","cta":"Visit Coins"},"land-l5-measure":{"id":"land-l5-measure","kind":"land","level":5,"src":"land:l5-measure","title":"Area and angles — in The Clock Tower","body":"4 stops on this stretch of the road: Perimeter · Area of a rectangle · Area of an L-shape · Angles on a line and round a point.","art":"art/w-clocktower.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Clock Tower · Level 5","route":"#/world/clocktower","cta":"Visit Clock Tower"},"land-l5-data":{"id":"land-l5-data","kind":"land","level":5,"src":"land:l5-data","title":"Averages and working back — in The Data Carnival","body":"3 stops on this stretch of the road: The mean: fair shares · The range: how spread out? · Working backwards.","art":"art/w-carnival.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Data Carnival · Level 5","route":"#/world/carnival","cta":"Visit Carnival"},"land-l5-contest":{"id":"land-l5-contest","kind":"land","level":5,"src":"land:l5-contest","title":"Counting with care — in The Figure Fair","body":"4 stops on this stretch of the road: Counting triangles · Counting rectangles · Handshakes and matches · Staircase perimeters.","art":"art/w-figures.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Figure Fair · Level 5","route":"#/world/figures","cta":"Visit Figure Fair"},"trick-long-multiply-idea":{"id":"trick-long-multiply-idea","kind":"trick","src":"stop:long-multiply#idea","title":"Long multiplication","body":"Split both numbers by place, multiply every part by every part in a grid, and add the boxes. 46 × 37 means 46 rows of 37. Split the 46 into 40 and 6, and the 37 into 30 and 7, and the rectangle cuts into four smaller rectangles: 40 × 30, 40 × 7, 6 × 30 and 6 × 7. Every one is a times-table fact with some zeros.","more":"In algebra: (10a + b)(10c + d) = 100ac + 10ad + 10bc + bd","cta":"Learn the trick","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn"},"story-long-multiply-open":{"id":"story-long-multiply-open","kind":"story","src":"story:long-multiply#open","badge":{"id":"story","label":"A story"},"title":"Tiling the reading room","body":"The reading-room floor is 46 tiles long and 37 tiles wide. How many tiles? — with Mira and Rafi.","more":"The trick inside: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","art":"art/s-library.webp","cta":"Read the story","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|story|0"},"hook-long-multiply-hook":{"id":"hook-long-multiply-hook","kind":"hook","src":"stop:long-multiply#hook","title":"Can you? — Long multiplication","body":"46 × 37 — both numbers too big for the tables.","more":"The way in: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"Find out how","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn"},"idea-long-multiply-case0":{"id":"idea-long-multiply-case0","kind":"idea","src":"stop:long-multiply#case0","title":"Long multiplication: Two-digit: the grid","body":"Two parts each way make four boxes. Every box is a times-table fact with zeros, and the four add up to the whole.","more":"The method: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"See it worked","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn|0"},"worked-long-multiply-worked0":{"id":"worked-long-multiply-worked0","kind":"worked","src":"stop:long-multiply#worked0","title":"Worked out — Long multiplication: Two-digit: the grid","body":"46 × 37: 40 × 30 → 1200 · 40 × 7 → 280 · 6 × 30 → 180 · 6 × 7 → 42 · Add all four boxes → 1702","more":"What is special here: Two parts each way make four boxes. Every box is a times-table fact with zeros, and the four add up to the whole.","cta":"Watch it step by step","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn|0"},"idea-long-multiply-case1":{"id":"idea-long-multiply-case1","kind":"idea","src":"stop:long-multiply#case1","title":"Long multiplication: Three-digit: two rows","body":"With a three-digit number, work in rows: the whole top number times the ones, then times the tens (write a 0 first). Add the two rows.","more":"The method: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"See it worked","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn|1"},"worked-long-multiply-worked1":{"id":"worked-long-multiply-worked1","kind":"worked","src":"stop:long-multiply#worked1","title":"Worked out — Long multiplication: Three-digit: two rows","body":"234 × 26: First row: 234 × 6 → 1404 · Second row: 234 × 20 (write a 0, then × 2) → 4680 · Add the two rows → 6084","more":"What is special here: With a three-digit number, work in rows: the whole top number times the ones, then times the tens (write a 0 first). Add the two rows.","cta":"Watch it step by step","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn|1"},"why-long-multiply-why1":{"id":"why-long-multiply-why1","kind":"why","src":"stop:long-multiply#why1","title":"Why “Long multiplication” works","body":"The four boxes cover the whole rectangle exactly once — no gaps, no overlaps — so their areas add up to the whole: 1200 + 280 + 180 + 42 = 1702.","more":"The trick: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn"},"why-long-multiply-why2":{"id":"why-long-multiply-why2","kind":"why","src":"stop:long-multiply#why2","title":"Why “Long multiplication” works","body":"The column method is the same grid folded up — and it is the quicker way once a number has three digits. The first row is the whole top number times the ones (46 × 7); the second row is it times the tens (46 × 30, which is why you write a 0 first). Add the two rows and you have added all the boxes.","more":"The trick: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn"},"algebra-long-multiply-alg":{"id":"algebra-long-multiply-alg","kind":"algebra","src":"stop:long-multiply#alg","title":"The algebra behind “Long multiplication”","body":"(10a + b)(10c + d) = 100ac + 10ad + 10bc + bd","more":"In words: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|learn"},"moment-long-multiply-beat3":{"id":"moment-long-multiply-beat3","kind":"moment","src":"story:long-multiply#beat3","badge":{"id":"story","label":"A story"},"title":"Tiling the reading room — on the notepad","body":"Mira: Two long strips. 40 × 7 + 6 × 30 = 460","more":"The trick in the story: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"Read the story","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|story|3"},"moral-long-multiply-beat5":{"id":"moral-long-multiply-beat5","kind":"moral","src":"story:long-multiply#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Tiling the reading room”","body":"Add all four pieces together: the whole floor.","more":"The trick in the story: Split both numbers by place, multiply every part by every part in a grid, and add the boxes.","cta":"Read the story","where":"The Number Library · Level 5","level":5,"route":"#/stop/long-multiply|story|5"},"try-long-multiply-L5":{"id":"try-long-multiply-L5","kind":"try","level":5,"src":"try:long-multiply@5/1#0","title":"Long multiplication — your turn","where":"The Number Library · Level 5","route":"#/stop/long-multiply|drill","cta":"Practise this stop","play":{"q":"17 × 12 = ?","opts":["204","100","20"],"after":"Split both numbers by place, multiply every part by every part in a grid, and add the boxes."}},"trick-order-of-operations-idea":{"id":"trick-order-of-operations-idea","kind":"trick","src":"stop:order-of-operations#idea","title":"Which sum first?","body":"Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right. A calculation written in a line could be read more than one way. 2 + 3 × 4 is 20 if you add first and 14 if you multiply first. Maths only works if everyone gets the same answer, so everyone agrees an order. You may know it as BODMAS or BIDMAS in Britain and India, or PEMDAS in America — they are the same rule.","more":"In algebra: Brackets → Orders (powers) → × ÷ (left to right) → + − (left to right)","cta":"Learn the trick","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn"},"story-order-of-operations-open":{"id":"story-order-of-operations-open","kind":"story","src":"story:order-of-operations#open","badge":{"id":"story","label":"A story"},"title":"The library quiz","body":"The quiz card at the library desk says: 2 + 3 × 4. — with Kwame and Pip.","more":"The trick inside: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","art":"art/s-library.webp","cta":"Read the story","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|story|0"},"hook-order-of-operations-hook":{"id":"hook-order-of-operations-hook","kind":"hook","src":"stop:order-of-operations#hook","title":"Can you? — Which sum first?","body":"2 + 3 × 4 — is it 20 or 14?","more":"The way in: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"Find out how","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn"},"idea-order-of-operations-case0":{"id":"idea-order-of-operations-case0","kind":"idea","src":"stop:order-of-operations#case0","title":"Which sum first?: × and ÷ before + and −","body":"A multiplication is one bundle — three fours is 12 — so work it out before you add anything to it.","more":"The method: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See it worked","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|0"},"worked-order-of-operations-worked0":{"id":"worked-order-of-operations-worked0","kind":"worked","src":"stop:order-of-operations#worked0","title":"Worked out — Which sum first?: × and ÷ before + and −","body":"2 + 3 × 4: Multiply first: 3 × 4 → 12 · 2 + 12 → 14","more":"What is special here: A multiplication is one bundle — three fours is 12 — so work it out before you add anything to it.","cta":"Watch it step by step","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|0"},"idea-order-of-operations-case1":{"id":"idea-order-of-operations-case1","kind":"idea","src":"stop:order-of-operations#case1","title":"Which sum first?: Brackets first","body":"Brackets change the order on purpose: whatever is inside them is done first, even an adding sum.","more":"The method: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See it worked","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|1"},"worked-order-of-operations-worked1":{"id":"worked-order-of-operations-worked1","kind":"worked","src":"stop:order-of-operations#worked1","title":"Worked out — Which sum first?: Brackets first","body":"(2 + 3) × 4: Brackets first: 2 + 3 → 5 · 5 × 4 → 20","more":"What is special here: Brackets change the order on purpose: whatever is inside them is done first, even an adding sum.","cta":"Watch it step by step","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|1"},"idea-order-of-operations-case2":{"id":"idea-order-of-operations-case2","kind":"idea","src":"stop:order-of-operations#case2","title":"Which sum first?: Powers before ×","body":"A power like 3² is a bundle too — 3 × 3 — and it comes before multiplying or adding.","more":"The method: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See it worked","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|2"},"worked-order-of-operations-worked2":{"id":"worked-order-of-operations-worked2","kind":"worked","src":"stop:order-of-operations#worked2","title":"Worked out — Which sum first?: Powers before ×","body":"5 + 3² × 2: Powers first: 3² → 9 · 9 × 2 → 18 · 5 + 18 → 23","more":"What is special here: A power like 3² is a bundle too — 3 × 3 — and it comes before multiplying or adding.","cta":"Watch it step by step","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|2"},"idea-order-of-operations-case3":{"id":"idea-order-of-operations-case3","kind":"idea","src":"stop:order-of-operations#case3","title":"Which sum first?: Same rank: left to right","body":"Do the × and ÷ bundles first. Then the + and − are the same rank, so go strictly left to right.","more":"The method: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See it worked","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|3"},"worked-order-of-operations-worked3":{"id":"worked-order-of-operations-worked3","kind":"worked","src":"stop:order-of-operations#worked3","title":"Worked out — Which sum first?: Same rank: left to right","body":"30 − 12 ÷ 4 + 2 × 5: 12 ÷ 4 → 3 · 2 × 5 → 10 · Now left to right: 30 − 3 → 27 · 27 + 10 → 37","more":"What is special here: Do the × and ÷ bundles first. Then the + and − are the same rank, so go strictly left to right.","cta":"Watch it step by step","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn|3"},"why-order-of-operations-why1":{"id":"why-order-of-operations-why1","kind":"why","src":"stop:order-of-operations#why1","title":"Why “Which sum first?” works","body":"Multiplying goes before adding because a multiplication is a bundle: 3 × 4 is \"three fours\", a single amount, 12. The 2 is added to that amount. If you want the 2 and 3 to go together first, you have to say so with brackets: (2 + 3) × 4.","more":"The trick: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn"},"why-order-of-operations-why2":{"id":"why-order-of-operations-why2","kind":"why","src":"stop:order-of-operations#why2","title":"Why “Which sum first?” works","body":"× and ÷ are the same rank, and so are + and −, so between those you just go left to right: 20 − 6 + 3 is 14 + 3 = 17, not 20 − 9.","more":"The trick: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn"},"why-order-of-operations-why3":{"id":"why-order-of-operations-why3","kind":"why","src":"stop:order-of-operations#why3","title":"Why “Which sum first?” works","body":"Powers come before × and ÷ because a power is a bundle of multiplications: 3² is 3 × 3, a single amount, 9. So 5 + 3² × 2 is 5 + 9 × 2 = 5 + 18 = 23.","more":"The trick: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn"},"algebra-order-of-operations-alg":{"id":"algebra-order-of-operations-alg","kind":"algebra","src":"stop:order-of-operations#alg","title":"The algebra behind “Which sum first?”","body":"Brackets → Orders (powers) → × ÷ (left to right) → + − (left to right)","more":"In words: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"See why","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|learn"},"moment-order-of-operations-beat3":{"id":"moment-order-of-operations-beat3","kind":"moment","src":"story:order-of-operations#beat3","badge":{"id":"story","label":"A story"},"title":"The library quiz — on the notepad","body":"Kwame: Then add the 2. 2 + 12 = 14","more":"The trick in the story: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"Read the story","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|story|3"},"moral-order-of-operations-beat6":{"id":"moral-order-of-operations-beat6","kind":"moral","src":"story:order-of-operations#beat6","badge":{"id":"story","label":"A story"},"title":"Pip, in “The library quiz”","body":"Without brackets, the card’s answer is 14.","more":"The trick in the story: Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right.","cta":"Read the story","where":"The Number Library · Level 5","level":5,"route":"#/stop/order-of-operations|story|6"},"try-order-of-operations-L5":{"id":"try-order-of-operations-L5","kind":"try","level":5,"src":"try:order-of-operations@5/1#0","title":"Which sum first? — your turn","where":"The Number Library · Level 5","route":"#/stop/order-of-operations|drill","cta":"Practise this stop","play":{"q":"38 − 2 × 4 = ?","opts":["30","8","31"],"after":"Brackets first, then powers, then × and ÷, then + and −. Same-rank steps go left to right."}},"hook-perimeter-hook":{"id":"hook-perimeter-hook","kind":"hook","src":"stop:perimeter#hook","title":"Can you? — Perimeter","body":"A garden is 8 m by 5 m. How much fence goes all the way round?","more":"The way in: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"Find out how","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/perimeter|learn"},"worked-perimeter-worked0":{"id":"worked-perimeter-worked0","kind":"worked","src":"stop:perimeter#worked0","title":"Worked out — Perimeter: A rectangle","body":"A rectangle is 8 cm long and 5 cm wide. What is its perimeter, in cm?: One length and one width: 8 + 5 → 13 · Two of each: double it → 26","more":"What is special here: Two lengths and two widths. Add one of each, then double it.","cta":"Watch it step by step","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/perimeter|learn|0"},"worked-perimeter-worked1":{"id":"worked-perimeter-worked1","kind":"worked","src":"stop:perimeter#worked1","title":"Worked out — Perimeter: A square","body":"A square has sides of 6 cm. What is its perimeter, in cm?: A square has four equal sides → 4 · 4 × 6 → 24","more":"What is special here: Only one side is given, because all four are the same. Four of them make the way round.","cta":"Watch it step by step","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/perimeter|learn|1"},"why-perimeter-why1":{"id":"why-perimeter-why1","kind":"why","src":"stop:perimeter#why1","title":"Why “Perimeter” works","body":"An L-shape looks harder, but it is not. Push the two sides of the cut-out corner outwards and they line up exactly with the missing corner of a full rectangle. The steps up and across still add up to the full height and the full width.","more":"The trick: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/perimeter|learn"},"algebra-perimeter-alg":{"id":"algebra-perimeter-alg","kind":"algebra","src":"stop:perimeter#alg","title":"The algebra behind “Perimeter”","body":"rectangle: P = 2(l + w) · L-shape: P = 2(W + H)","more":"In words: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/perimeter|learn"},"moral-perimeter-beat5":{"id":"moral-perimeter-beat5","kind":"moral","src":"story:perimeter#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Fencing the vegetable patch”","body":"Twenty-six metres of fence, all the way round.","more":"The trick in the story: Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width).","cta":"Read the story","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/perimeter|story|5"},"try-perimeter-L5":{"id":"try-perimeter-L5","kind":"try","level":5,"src":"try:perimeter@5/2#0","title":"Perimeter — your turn","where":"The Clock Tower · Level 5","route":"#/stop/perimeter|drill","cta":"Practise this stop","play":{"q":"A square has sides of 8 cm. What is its perimeter, in cm?","opts":["32","4","33"],"after":"Perimeter is the distance all the way round: add every side. A rectangle has two of each side, so double (length + width)."}},"hook-area-rectangles-hook":{"id":"hook-area-rectangles-hook","kind":"hook","src":"stop:area-rectangles#hook","title":"Can you? — Area of a rectangle","body":"A rug is 7 squares long and 6 squares wide. How many squares does it cover — without counting them all?","more":"The way in: Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width.","cta":"Find out how","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/area-rectangles|learn"},"idea-area-rectangles-case1":{"id":"idea-area-rectangles-case1","kind":"idea","src":"stop:area-rectangles#case1","title":"Area of a rectangle: Length × width","body":"The length is how many squares fit in a row and the width is how many rows, so the area is the two multiplied.","more":"The method: Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width.","cta":"See it worked","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/area-rectangles|learn|1"},"idea-area-rectangles-case2":{"id":"idea-area-rectangles-case2","kind":"idea","src":"stop:area-rectangles#case2","title":"Area of a rectangle: Finding a missing side","body":"Now the area is given and a side is missing. Undo the multiplying: divide the area by the side you know.","more":"The method: Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width.","cta":"See it worked","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/area-rectangles|learn|2"},"why-area-rectangles-why1":{"id":"why-area-rectangles-why1","kind":"why","src":"stop:area-rectangles#why1","title":"Why “Area of a rectangle” works","body":"Lay the squares in a rectangle and they make neat rows. Every row has the same number of squares — the length — and there are as many rows as the width. Equal rows are exactly what multiplying counts: 6 rows of 7 is 6 × 7 = 42.","more":"The trick: Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width.","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/area-rectangles|learn"},"algebra-area-rectangles-alg":{"id":"algebra-area-rectangles-alg","kind":"algebra","src":"stop:area-rectangles#alg","title":"The algebra behind “Area of a rectangle”","body":"A = l × w · w = A ÷ l","more":"In words: Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width.","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/area-rectangles|learn"},"moral-area-rectangles-beat5":{"id":"moral-area-rectangles-beat5","kind":"moral","src":"story:area-rectangles#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The new rug”","body":"Forty-two squares. Length times width!","more":"The trick in the story: Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width.","cta":"Read the story","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/area-rectangles|story|5"},"try-area-rectangles-L5":{"id":"try-area-rectangles-L5","kind":"try","level":5,"src":"try:area-rectangles@5/2#0","title":"Area of a rectangle — your turn","where":"The Clock Tower · Level 5","route":"#/stop/area-rectangles|drill","cta":"Practise this stop","play":{"q":"A rectangle is 2 cm long and 11 cm wide. What is its area, in cm²?","opts":["22","2","11"],"after":"Area is how many unit squares cover a shape. A rectangle is rows of equal squares, so area = length × width."}},"trick-compound-area-idea":{"id":"trick-compound-area-idea","kind":"trick","src":"stop:compound-area#idea","title":"Area of an L-shape","body":"Cut the L into two rectangles, find each area, and add them. Area does not change when you cut a shape up: the same floor is covered, just in two pieces. So an L-shape can be split with one straight line into two rectangles, and each rectangle is length × width.","more":"In algebra: A = W × h₁ + w₁ × (H − h₁) = W × H − (W − w₁)(H − h₁)","cta":"Learn the trick","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|learn"},"story-compound-area-open":{"id":"story-compound-area-open","kind":"story","src":"story:compound-area#open","badge":{"id":"story","label":"A story"},"title":"Carpet for the L-shaped hall","body":"A hall is shaped like an L: 8 m across the bottom, 7 m up the side, with a corner missing. — with Rafi and Ines.","more":"The trick inside: Cut the L into two rectangles, find each area, and add them.","art":"art/s-hall.webp","cta":"Read the story","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|story|0"},"hook-compound-area-hook":{"id":"hook-compound-area-hook","kind":"hook","src":"stop:compound-area#hook","title":"Can you? — Area of an L-shape","body":"A room is shaped like an L. How much carpet does it need?","more":"The way in: Cut the L into two rectangles, find each area, and add them.","cta":"Find out how","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|learn"},"why-compound-area-why1":{"id":"why-compound-area-why1","kind":"why","src":"stop:compound-area#why1","title":"Why “Area of an L-shape” works","body":"The only work is finding the sides of each piece. The height of the upper piece is the full height take away the bottom strip, because the two heights stack to make the whole side.","more":"The trick: Cut the L into two rectangles, find each area, and add them.","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|learn"},"why-compound-area-why2":{"id":"why-compound-area-why2","kind":"why","src":"stop:compound-area#why2","title":"Why “Area of an L-shape” works","body":"There is a second road to the same answer: the L is the full rectangle around it with one corner missing. Full rectangle minus the missing corner must give the same number — which is a good way to check.","more":"The trick: Cut the L into two rectangles, find each area, and add them.","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|learn"},"algebra-compound-area-alg":{"id":"algebra-compound-area-alg","kind":"algebra","src":"stop:compound-area#alg","title":"The algebra behind “Area of an L-shape”","body":"A = W × h₁ + w₁ × (H − h₁) = W × H − (W − w₁)(H − h₁)","more":"In words: Cut the L into two rectangles, find each area, and add them.","cta":"See why","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|learn"},"moment-compound-area-beat3":{"id":"moment-compound-area-beat3","kind":"moment","src":"story:compound-area#beat3","badge":{"id":"story","label":"A story"},"title":"Carpet for the L-shaped hall — on the notepad","body":"Ines: The part above is 3 m wide and 7 − 3 = 4 m tall. 3 × 4 = 12","more":"The trick in the story: Cut the L into two rectangles, find each area, and add them.","cta":"Read the story","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|story|3"},"moral-compound-area-beat5":{"id":"moral-compound-area-beat5","kind":"moral","src":"story:compound-area#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Carpet for the L-shaped hall”","body":"Both roads agree — 36 square metres of carpet.","more":"The trick in the story: Cut the L into two rectangles, find each area, and add them.","cta":"Read the story","where":"The Clock Tower · Level 5","level":5,"route":"#/stop/compound-area|story|5"},"hook-equivalent-fractions-hook":{"id":"hook-equivalent-fractions-hook","kind":"hook","src":"stop:equivalent-fractions#hook","title":"Can you? — Same share, different pieces","body":"3/4 = ?/12 — how many twelfths is three quarters?","more":"The way in: Whatever you do to the bottom, do the same to the top.","cta":"Find out how","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/equivalent-fractions|learn"},"worked-equivalent-fractions-worked0":{"id":"worked-equivalent-fractions-worked0","kind":"worked","src":"stop:equivalent-fractions#worked0","title":"Worked out — Same share, different pieces: Missing top","body":"3/4 = ?/12: 4 × what makes 12? → 3 · Same to the top: 3 × 3 → 9","more":"What is special here: Work out what the bottom was multiplied by, then do the same to the top.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/equivalent-fractions|learn|0"},"worked-equivalent-fractions-worked1":{"id":"worked-equivalent-fractions-worked1","kind":"worked","src":"stop:equivalent-fractions#worked1","title":"Worked out — Same share, different pieces: Missing bottom","body":"2/3 = 8/?: 2 × what makes 8? → 4 · Same to the bottom: 3 × 4 → 12","more":"What is special here: This time the tops tell you the multiplier. Do the same to the bottom.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/equivalent-fractions|learn|1"},"worked-equivalent-fractions-worked2":{"id":"worked-equivalent-fractions-worked2","kind":"worked","src":"stop:equivalent-fractions#worked2","title":"Worked out — Same share, different pieces: Going down: dividing","body":"10/15 = ?/3: 15 ÷ what makes 3? → 5 · Same to the top: 10 ÷ 5 → 2","more":"What is special here: The new bottom is smaller, so the pieces are being glued back together: divide the top by the same number.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/equivalent-fractions|learn|2"},"why-equivalent-fractions-why2":{"id":"why-equivalent-fractions-why2","kind":"why","src":"stop:equivalent-fractions#why2","title":"Why “Same share, different pieces” works","body":"It works backwards too. 9/12 can be glued back into bigger pieces by dividing top and bottom by the same number. Multiply or divide — as long as it is the same number, top and bottom, the share never changes.","more":"The trick: Whatever you do to the bottom, do the same to the top.","cta":"See why","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/equivalent-fractions|learn"},"moment-equivalent-fractions-beat3":{"id":"moment-equivalent-fractions-beat3","kind":"moment","src":"story:equivalent-fractions#beat3","badge":{"id":"story","label":"A story"},"title":"Smaller slices — on the notepad","body":"Rafi: And your 3 quarters become… 3 × 3 = 9","more":"The trick in the story: Whatever you do to the bottom, do the same to the top.","cta":"Read the story","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/equivalent-fractions|story|3"},"try-equivalent-fractions-L5":{"id":"try-equivalent-fractions-L5","kind":"try","level":5,"src":"try:equivalent-fractions@5/2#0","title":"Same share, different pieces — your turn","where":"The Fraction Bakery · Level 5","route":"#/stop/equivalent-fractions|drill","cta":"Practise this stop","play":{"q":"4/5 = 8/?","opts":["10","2","11"],"after":"Whatever you do to the bottom, do the same to the top."}},"hook-compare-fractions-hook":{"id":"hook-compare-fractions-hook","kind":"hook","src":"stop:compare-fractions#hook","title":"Can you? — Which slice is bigger?","body":"3/5 or 4/7 — which is more cake?","more":"The way in: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"Find out how","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|learn"},"worked-compare-fractions-worked0":{"id":"worked-compare-fractions-worked0","kind":"worked","src":"stop:compare-fractions#worked0","title":"Worked out — Which slice is bigger?: Same bottoms","body":"5/8  ?  3/8: Same-size pieces. How many on the left? → 5 · …and on the right? → 3 · Compare → >","more":"What is special here: Same bottom, same size of piece — so whoever has more pieces has more.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|learn|0"},"worked-compare-fractions-worked1":{"id":"worked-compare-fractions-worked1","kind":"worked","src":"stop:compare-fractions#worked1","title":"Worked out — Which slice is bigger?: Same tops","body":"2/5  ?  2/7: Same number of pieces. Which cut makes bigger pieces: 5 or 7? → 5 · Compare → >","more":"What is special here: The same number of pieces each, so the bigger pieces win — and fewer cuts make bigger pieces. The smaller bottom is more.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|learn|1"},"worked-compare-fractions-worked2":{"id":"worked-compare-fractions-worked2","kind":"worked","src":"stop:compare-fractions#worked2","title":"Worked out — Which slice is bigger?: Nothing matches","body":"3/5  ?  4/7: 3 × 7 → 21 · 4 × 5 → 20 · Compare → >","more":"What is special here: Cross-multiply: each top times the other bottom. Those are the tops you would get with a shared bottom.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|learn|2"},"worked-compare-fractions-worked3":{"id":"worked-compare-fractions-worked3","kind":"worked","src":"stop:compare-fractions#worked3","title":"Worked out — Which slice is bigger?: Equal after all","body":"2/4  ?  3/6: 2 × 6 → 12 · 3 × 4 → 12 · Compare → =","more":"What is special here: Different numbers can name the same share. When the cross-multiplied tops match, the answer is =.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|learn|3"},"why-compare-fractions-why2":{"id":"why-compare-fractions-why2","kind":"why","src":"stop:compare-fractions#why2","title":"Why “Which slice is bigger?” works","body":"If nothing matches, cut both into the same pieces. 3/5 and 4/7 both become thirty-fifths: 3/5 = 21/35 and 4/7 = 20/35. You never need the 35 — the two new tops, 3 × 7 and 4 × 5, are all you compare. That is cross-multiplying. If the two new tops come out the same, the fractions are equal: two names for one share, like 2/4 and 3/6.","more":"The trick: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"See why","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|learn"},"moment-compare-fractions-beat4":{"id":"moment-compare-fractions-beat4","kind":"moment","src":"story:compare-fractions#beat4","badge":{"id":"story","label":"A story"},"title":"Two birthday cakes — on the notepad","body":"Theo: Chocolate: 4 times 5. 4 × 5 = 20","more":"The trick in the story: Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply.","cta":"Read the story","where":"The Fraction Bakery · Level 5","level":5,"route":"#/stop/compare-fractions|story|4"},"try-compare-fractions-L5":{"id":"try-compare-fractions-L5","kind":"try","level":5,"src":"try:compare-fractions@5/2#0","title":"Which slice is bigger? — your turn","where":"The Fraction Bakery · Level 5","route":"#/stop/compare-fractions|drill","cta":"Practise this stop","play":{"q":"1/7  ?  1/5","opts":["<","=",">"],"after":"Same bottoms: compare the tops. Same tops: the smaller bottom wins. Otherwise cross-multiply."}},"trick-best-buy-idea":{"id":"trick-best-buy-idea","kind":"trick","src":"stop:best-buy#idea","title":"The best buy","body":"Find the price of ONE from each pack — or of the same number from each — then compare like with like. A bigger pack costs more, so the prices on their own tell you nothing. What matters is what each apple costs. 28 ÷ 4 is 7 coins an apple; 36 ÷ 6 is 6 coins an apple. The bigger pack is the better buy — this time.","more":"In algebra: A is the better buy when priceA ÷ countA < priceB ÷ countB (or priceA × countB < priceB × countA)","cta":"Learn the trick","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn"},"story-best-buy-open":{"id":"story-best-buy-open","kind":"story","src":"story:best-buy#open","badge":{"id":"story","label":"A story"},"title":"Two bags of apples","body":"At the fruit stall, a bag of 4 apples is 28 coins and a bag of 6 apples is 36 coins. — with Ines and Pip.","more":"The trick inside: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","art":"art/s-market.webp","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|story|0"},"hook-best-buy-hook":{"id":"hook-best-buy-hook","kind":"hook","src":"stop:best-buy#hook","title":"Can you? — The best buy","body":"4 apples for 28 coins, or 6 apples for 36 coins. Which is cheaper for each apple?","more":"The way in: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"Find out how","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn"},"idea-best-buy-case0":{"id":"idea-best-buy-case0","kind":"idea","src":"stop:best-buy#case0","title":"The best buy: Price of one","body":"Both prices share out evenly, so find what ONE costs from each pack and compare.","more":"The method: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn|0"},"worked-best-buy-worked0":{"id":"worked-best-buy-worked0","kind":"worked","src":"stop:best-buy#worked0","title":"Worked out — The best buy: Price of one","body":"Pack A: 4 apples for 28 coins. Pack B: 6 apples for 36 coins. Which is cheaper for each apple?: One from A: 28 ÷ 4 → 7 · One from B: 36 ÷ 6 → 6 · Which is cheaper each? → Pack B","more":"What is special here: Both prices share out evenly, so find what ONE costs from each pack and compare.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn|0"},"idea-best-buy-case1":{"id":"idea-best-buy-case1","kind":"idea","src":"stop:best-buy#case1","title":"The best buy: Price of the same number","body":"One would be a messy number, so price the same number from both packs — a number both pack sizes go into.","more":"The method: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn|1"},"worked-best-buy-worked1":{"id":"worked-best-buy-worked1","kind":"worked","src":"stop:best-buy#worked1","title":"Worked out — The best buy: Price of the same number","body":"Pack A: 5 pencils for 12 coins. Pack B: 3 pencils for 8 coins. Which is cheaper for each pencil?: 15 from A: 12 × 3 → 36 · 15 from B: 8 × 5 → 40 · Which is cheaper each? → Pack A","more":"What is special here: One would be a messy number, so price the same number from both packs — a number both pack sizes go into.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn|1"},"why-best-buy-why1":{"id":"why-best-buy-why1","kind":"why","src":"stop:best-buy#why1","title":"Why “The best buy” works","body":"Sometimes one apple works out to a messy number. Then price the SAME number from both packs instead. 5 for 12 and 3 for 8: 15 apples from the first pack is 3 lots, 36 coins; 15 from the second is 5 lots, 40 coins. The first is cheaper, and nobody had to divide.","more":"The trick: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn"},"why-best-buy-why2":{"id":"why-best-buy-why2","kind":"why","src":"stop:best-buy#why2","title":"Why “The best buy” works","body":"Cheaper each is not always better for you — ten apples you will not eat are not a bargain. The maths tells you the price; you still decide what you need.","more":"The trick: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn"},"algebra-best-buy-alg":{"id":"algebra-best-buy-alg","kind":"algebra","src":"stop:best-buy#alg","title":"The algebra behind “The best buy”","body":"A is the better buy when priceA ÷ countA < priceB ÷ countB (or priceA × countB < priceB × countA)","more":"In words: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|learn"},"moment-best-buy-beat3":{"id":"moment-best-buy-beat3","kind":"moment","src":"story:best-buy#beat3","badge":{"id":"story","label":"A story"},"title":"Two bags of apples — on the notepad","body":"Pip: And the big bag… 36 ÷ 6 = 6","more":"The trick in the story: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|story|3"},"moral-best-buy-beat5":{"id":"moral-best-buy-beat5","kind":"moral","src":"story:best-buy#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Two bags of apples”","body":"The big bag, then — as long as we eat all six.","more":"The trick in the story: Find the price of ONE from each pack — or of the same number from each — then compare like with like.","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/best-buy|story|5"},"try-best-buy-L5":{"id":"try-best-buy-L5","kind":"try","level":5,"src":"try:best-buy@5/1#0","title":"The best buy — your turn","where":"Coin Street · Level 5","route":"#/stop/best-buy|drill","cta":"Practise this stop","play":{"q":"Pack A: 2 samosas for 12 coins. Pack B: 5 samosas for 25 coins. Which is cheaper for each samosa?","opts":["Pack B","Pack A"],"after":"Find the price of ONE from each pack — or of the same number from each — then compare like with like."}},"trick-fraction-off-idea":{"id":"trick-fraction-off-idea","kind":"trick","src":"stop:fraction-off#idea","title":"A sale","body":"Find the fraction of the price that comes off, then take it away from the price. \"1/4 off\" means the price is cut into 4 equal parts and one part is taken away. One quarter of 40 is 40 ÷ 4 = 10, so 10 coins come off and the kite costs 30.","more":"In algebra: price with k/d off = price − price ÷ d × k = price ÷ d × (d − k)","cta":"Learn the trick","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn"},"story-fraction-off-open":{"id":"story-fraction-off-open","kind":"story","src":"story:fraction-off#open","badge":{"id":"story","label":"A story"},"title":"The sale sign","body":"In the sports shop, a 40-coin kite has a sign on it: 1/4 off. — with Nova and Rafi.","more":"The trick inside: Find the fraction of the price that comes off, then take it away from the price.","art":"art/s-shop.webp","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|story|0"},"hook-fraction-off-hook":{"id":"hook-fraction-off-hook","kind":"hook","src":"stop:fraction-off#hook","title":"Can you? — A sale","body":"A 40-coin kite has 1/4 off in the sale. What does it cost now?","more":"The way in: Find the fraction of the price that comes off, then take it away from the price.","cta":"Find out how","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn"},"idea-fraction-off-case0":{"id":"idea-fraction-off-case0","kind":"idea","src":"stop:fraction-off#case0","title":"A sale: One part off","body":"With 1 on top, one share comes off: divide the price by the bottom number, then take that away.","more":"The method: Find the fraction of the price that comes off, then take it away from the price.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn|0"},"worked-fraction-off-worked0":{"id":"worked-fraction-off-worked0","kind":"worked","src":"stop:fraction-off#worked0","title":"Worked out — A sale: One part off","body":"A 40-coin kite has 1/4 off in the sale. What does it cost now?: 1/4 of 40: 40 ÷ 4 → 10 · Take it off: 40 − 10 → 30","more":"What is special here: With 1 on top, one share comes off: divide the price by the bottom number, then take that away.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn|0"},"idea-fraction-off-case1":{"id":"idea-fraction-off-case1","kind":"idea","src":"stop:fraction-off#case1","title":"A sale: Several parts off","body":"Find one share, multiply by the top number to get the whole discount, then take it off the price.","more":"The method: Find the fraction of the price that comes off, then take it away from the price.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn|1"},"worked-fraction-off-worked1":{"id":"worked-fraction-off-worked1","kind":"worked","src":"stop:fraction-off#worked1","title":"Worked out — A sale: Several parts off","body":"A 40-coin puzzle has 2/5 off in the sale. What does it cost now?: 1/5 of 40: 40 ÷ 5 → 8 · 2/5 off: 8 × 2 → 16 · Take it off: 40 − 16 → 24","more":"What is special here: Find one share, multiply by the top number to get the whole discount, then take it off the price.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn|1"},"why-fraction-off-why1":{"id":"why-fraction-off-why1","kind":"why","src":"stop:fraction-off#why1","title":"Why “A sale” works","body":"For 2/5 off, find one fifth and double it: 2/5 of 40 is 8 × 2 = 16 off, so it costs 24. The bar shows the shaded parts that come off and the plain parts you still pay.","more":"The trick: Find the fraction of the price that comes off, then take it away from the price.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn"},"why-fraction-off-why2":{"id":"why-fraction-off-why2","kind":"why","src":"stop:fraction-off#why2","title":"Why “A sale” works","body":"You can also count the parts you DO pay: with 1/4 off you pay 3/4 of the price, and 3/4 of 40 is 30. Same answer by a different road — a good way to check. A sale lowers the price, but it is only a saving if you wanted the thing anyway.","more":"The trick: Find the fraction of the price that comes off, then take it away from the price.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn"},"algebra-fraction-off-alg":{"id":"algebra-fraction-off-alg","kind":"algebra","src":"stop:fraction-off#alg","title":"The algebra behind “A sale”","body":"price with k/d off = price − price ÷ d × k = price ÷ d × (d − k)","more":"In words: Find the fraction of the price that comes off, then take it away from the price.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|learn"},"moment-fraction-off-beat2":{"id":"moment-fraction-off-beat2","kind":"moment","src":"story:fraction-off#beat2","badge":{"id":"story","label":"A story"},"title":"The sale sign — on the notepad","body":"Nova: One part comes off. Take it away from the price. 40 − 10 = 30","more":"The trick in the story: Find the fraction of the price that comes off, then take it away from the price.","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|story|2"},"moral-fraction-off-beat4":{"id":"moral-fraction-off-beat4","kind":"moral","src":"story:fraction-off#beat4","badge":{"id":"story","label":"A story"},"title":"Nova, in “The sale sign”","body":"Same answer both ways. 30 coins.","more":"The trick in the story: Find the fraction of the price that comes off, then take it away from the price.","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/fraction-off|story|4"},"try-fraction-off-L5":{"id":"try-fraction-off-L5","kind":"try","level":5,"src":"try:fraction-off@5/1#0","title":"A sale — your turn","where":"Coin Street · Level 5","route":"#/stop/fraction-off|drill","cta":"Practise this stop","play":{"q":"A 100-coin football has 1/10 off in the sale. What does it cost now?","opts":["90","10","91"],"after":"Find the fraction of the price that comes off, then take it away from the price."}},"trick-profit-and-loss-idea":{"id":"trick-profit-and-loss-idea","kind":"trick","src":"stop:profit-and-loss#idea","title":"Profit and loss","body":"Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit. The coins that come in from selling are the takings: 14 cups at 4 coins each is 56 coins. But the stall did not get those lemons free — 30 coins went out first. Profit is what is left after paying for everything: 56 − 30 = 26.","more":"In algebra: profit = number sold × price − costs  (negative means a loss)","cta":"Learn the trick","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn"},"story-profit-and-loss-open":{"id":"story-profit-and-loss-open","kind":"story","src":"story:profit-and-loss#open","badge":{"id":"story","label":"A story"},"title":"The lemonade stall","body":"At the street festival, Dax and Ines run a lemonade stall. Lemons and sugar cost 30 coins. — with Ines and Dax.","more":"The trick inside: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","art":"art/s-festival.webp","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|story|0"},"hook-profit-and-loss-hook":{"id":"hook-profit-and-loss-hook","kind":"hook","src":"stop:profit-and-loss#hook","title":"Can you? — Profit and loss","body":"A lemonade stall spends 30 coins on lemons and sugar and sells 14 cups at 4 coins each. What is the profit?","more":"The way in: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"Find out how","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn"},"idea-profit-and-loss-case0":{"id":"idea-profit-and-loss-case0","kind":"idea","src":"stop:profit-and-loss#case0","title":"Profit and loss: A profit","body":"Work out the takings first — how many sold times the price — then take away what was spent.","more":"The method: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|0"},"worked-profit-and-loss-worked0":{"id":"worked-profit-and-loss-worked0","kind":"worked","src":"stop:profit-and-loss#worked0","title":"Worked out — Profit and loss: A profit","body":"A lemonade stall spends 30 coins on lemons and sugar, then sells 14 cups at 4 coins each. What is the profit?: Takings: 14 × 4 → 56 · Profit: 56 − 30 → 26","more":"What is special here: Work out the takings first — how many sold times the price — then take away what was spent.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|0"},"idea-profit-and-loss-case1":{"id":"idea-profit-and-loss-case1","kind":"idea","src":"stop:profit-and-loss#case1","title":"Profit and loss: Two costs to pay","body":"Everything that went out counts: add the materials and the pitch together before you take them away.","more":"The method: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|1"},"worked-profit-and-loss-worked1":{"id":"worked-profit-and-loss-worked1","kind":"worked","src":"stop:profit-and-loss#worked1","title":"Worked out — Profit and loss: Two costs to pay","body":"A bake stall spends 20 coins on flour and butter and pays 10 coins for its pitch, then sells 12 biscuits at 5 coins each. What is the profit? (Write a loss as a negative number.): Takings: 12 × 5 → 60 · Everything spent: 20 + 10 → 30 · Profit: 60 − 30 → 30","more":"What is special here: Everything that went out counts: add the materials and the pitch together before you take them away.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|1"},"idea-profit-and-loss-case2":{"id":"idea-profit-and-loss-case2","kind":"idea","src":"stop:profit-and-loss#case2","title":"Profit and loss: A loss","body":"More went out than came in, so the profit is below zero. Write it with a minus sign: that is a loss.","more":"The method: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|2"},"worked-profit-and-loss-worked2":{"id":"worked-profit-and-loss-worked2","kind":"worked","src":"stop:profit-and-loss#worked2","title":"Worked out — Profit and loss: A loss","body":"A badge stall spends 50 coins on pins and card and pays 15 coins for its pitch, then sells 10 badges at 6 coins each. What is the profit? (Write a loss as a negative number.): Takings: 10 × 6 → 60 · Everything spent: 50 + 15 → 65 · Profit: 60 − 65 → -5","more":"What is special here: More went out than came in, so the profit is below zero. Write it with a minus sign: that is a loss.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|2"},"idea-profit-and-loss-case3":{"id":"idea-profit-and-loss-case3","kind":"idea","src":"stop:profit-and-loss#case3","title":"Profit and loss: Breaking even","body":"The takings exactly cover the costs. Nothing gained, nothing lost: the profit is 0.","more":"The method: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See it worked","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|3"},"worked-profit-and-loss-worked3":{"id":"worked-profit-and-loss-worked3","kind":"worked","src":"stop:profit-and-loss#worked3","title":"Worked out — Profit and loss: Breaking even","body":"A plant stall spends 30 coins on pots and soil and pays 10 coins for its pitch, then sells 8 seedlings at 5 coins each. What is the profit? (Write a loss as a negative number.): Takings: 8 × 5 → 40 · Everything spent: 30 + 10 → 40 · Profit: 40 − 40 → 0","more":"What is special here: The takings exactly cover the costs. Nothing gained, nothing lost: the profit is 0.","cta":"Watch it step by step","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn|3"},"why-profit-and-loss-why1":{"id":"why-profit-and-loss-why1","kind":"why","src":"stop:profit-and-loss#why1","title":"Why “Profit and loss” works","body":"Takings are not profit. A stall that takes 56 coins and spent 60 has made a loss of 4. Writing that as −4 keeps one rule for both: profit = in − out, and the sign says which way it went. If there is more than one cost — materials and a pitch — add all the costs first. And if the takings exactly match the costs, the profit is 0: the stall has broken even.","more":"The trick: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn"},"why-profit-and-loss-why2":{"id":"why-profit-and-loss-why2","kind":"why","src":"stop:profit-and-loss#why2","title":"Why “Profit and loss” works","body":"A loss is not a disaster, it is information — it tells the stall-keeper to change the price, the costs or how many they make. Every business uses this one subtraction to decide what to do next.","more":"The trick: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn"},"algebra-profit-and-loss-alg":{"id":"algebra-profit-and-loss-alg","kind":"algebra","src":"stop:profit-and-loss#alg","title":"The algebra behind “Profit and loss”","body":"profit = number sold × price − costs  (negative means a loss)","more":"In words: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"See why","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|learn"},"moment-profit-and-loss-beat3":{"id":"moment-profit-and-loss-beat3","kind":"moment","src":"story:profit-and-loss#beat3","badge":{"id":"story","label":"A story"},"title":"The lemonade stall — on the notepad","body":"Ines: We took in 56. But 30 went out first, on lemons. Profit is in minus out. 56 − 30 = 26","more":"The trick in the story: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|story|3"},"moral-profit-and-loss-beat5":{"id":"moral-profit-and-loss-beat5","kind":"moral","src":"story:profit-and-loss#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The lemonade stall”","body":"And now we know what a cup costs us to make — so we can price it next time.","more":"The trick in the story: Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit.","cta":"Read the story","where":"Coin Street · Level 5","level":5,"route":"#/stop/profit-and-loss|story|5"},"try-profit-and-loss-L5":{"id":"try-profit-and-loss-L5","kind":"try","level":5,"src":"try:profit-and-loss@5/1#0","title":"Profit and loss — your turn","where":"Coin Street · Level 5","route":"#/stop/profit-and-loss|drill","cta":"Practise this stop","play":{"q":"A bracelet stall spends 42 coins on beads and thread, then sells 10 bracelets at 5 coins each. What is the profit?","opts":["8","50","9"],"after":"Profit is what comes in minus what went out. If more went out than came in, it is a loss — a negative profit."}},"trick-angles-on-a-line-idea":{"id":"trick-angles-on-a-line-idea","kind":"trick","src":"stop:angles-on-a-line#idea","title":"Angles on a line and round a point","body":"Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know. A straight line is half a turn. Stand on the point facing along the line and turn until you face back the other way: that is 180°. Each angle on the line is one part of that same half-turn, so the parts must add up to 180°.","more":"In algebra: a + b = 180° on a line · a + b + c + … = 360° round a point","cta":"Learn the trick","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|learn"},"story-angles-on-a-line-open":{"id":"story-angles-on-a-line-open","kind":"story","src":"story:angles-on-a-line#open","badge":{"id":"story","label":"A story"},"title":"The see-saw","body":"A ramp leans on a flat path by the stadium. On one side it makes an angle of 125° with the path. — with Theo and Ines.","more":"The trick inside: Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know.","art":"art/s-stadium.webp","cta":"Read the story","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|story|0"},"idea-angles-on-a-line-case0":{"id":"idea-angles-on-a-line-case0","kind":"idea","src":"stop:angles-on-a-line#case0","title":"Angles on a line and round a point: On a straight line","body":"A straight line is half a turn, so the angles along it share 180° between them.","more":"The method: Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know.","cta":"See it worked","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|learn|0"},"idea-angles-on-a-line-case1":{"id":"idea-angles-on-a-line-case1","kind":"idea","src":"stop:angles-on-a-line#case1","title":"Angles on a line and round a point: Round a point","body":"All the way round is a whole turn, 360°. Add every angle you know first, then see what is left.","more":"The method: Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know.","cta":"See it worked","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|learn|1"},"why-angles-on-a-line-why1":{"id":"why-angles-on-a-line-why1","kind":"why","src":"stop:angles-on-a-line#why1","title":"Why “Angles on a line and round a point” works","body":"All the way round a point is a whole turn — you end up facing where you started — and a whole turn is 360°. However many angles the rays cut it into, together they are the full 360°.","more":"The trick: Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know.","cta":"See why","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|learn"},"algebra-angles-on-a-line-alg":{"id":"algebra-angles-on-a-line-alg","kind":"algebra","src":"stop:angles-on-a-line#alg","title":"The algebra behind “Angles on a line and round a point”","body":"a + b = 180° on a line · a + b + c + … = 360° round a point","more":"In words: Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know.","cta":"See why","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|learn"},"moral-angles-on-a-line-beat6":{"id":"moral-angles-on-a-line-beat6","kind":"moral","src":"story:angles-on-a-line#beat6","badge":{"id":"story","label":"A story"},"title":"Theo, in “The see-saw”","body":"So the missing angle is 55°.","more":"The trick in the story: Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know.","cta":"Read the story","where":"Shape City · Level 5","level":5,"route":"#/stop/angles-on-a-line|story|6"},"try-angles-on-a-line-L5":{"id":"try-angles-on-a-line-L5","kind":"try","level":5,"src":"try:angles-on-a-line@5/1#0","title":"Angles on a line and round a point — your turn","where":"Shape City · Level 5","route":"#/stop/angles-on-a-line|drill","cta":"Practise this stop","play":{"q":"Angles on a straight line: 105° and ?. Find the missing angle.","opts":["75","180","105"],"after":"Angles on a straight line add up to 180°; angles all the way round a point add up to 360°. Take away the ones you know."}},"trick-divisible-4-8-idea":{"id":"trick-divisible-4-8-idea","kind":"trick","src":"stop:divisible-4-8#idea","title":"Tests for 4 and 8","body":"For 4, test just the last two digits. For 8, the last three. 100 is 4 × 25, so every whole hundred divides by 4. 73,516 is 73,500 + 16, and the 73,500 is a whole number of hundreds — it takes care of itself. Only the 16 is left to check, and 16 = 4 × 4.","more":"In algebra: 4 | 100 ⇒ test n mod 100 ; 8 | 1000 ⇒ test n mod 1000","cta":"Learn the trick","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn"},"story-divisible-4-8-open":{"id":"story-divisible-4-8-open","kind":"story","src":"story:divisible-4-8#open","badge":{"id":"story","label":"A story"},"title":"The seed packets","body":"The seed library has 73,516 seeds to share into packets of 4. — with Rafi and Suki.","more":"The trick inside: For 4, test just the last two digits. For 8, the last three.","art":"art/s-garden.webp","cta":"Read the story","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|story|0"},"hook-divisible-4-8-hook":{"id":"hook-divisible-4-8-hook","kind":"hook","src":"stop:divisible-4-8#hook","title":"Can you? — Tests for 4 and 8","body":"Is 73,516 in the 4 times table? No long division.","more":"The way in: For 4, test just the last two digits. For 8, the last three.","cta":"Find out how","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn"},"idea-divisible-4-8-case0":{"id":"idea-divisible-4-8-case0","kind":"idea","src":"stop:divisible-4-8#case0","title":"Tests for 4 and 8: Divisible by 4","body":"Every hundred splits into fours, so only the last TWO digits decide.","more":"The method: For 4, test just the last two digits. For 8, the last three.","cta":"See it worked","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn|0"},"worked-divisible-4-8-worked0":{"id":"worked-divisible-4-8-worked0","kind":"worked","src":"stop:divisible-4-8#worked0","title":"Worked out — Tests for 4 and 8: Divisible by 4","body":"Is 73,516 divisible by 4?: The last two digits of 73,516 → 16 · Is 16 in the 4 times table? → Yes","more":"What is special here: Every hundred splits into fours, so only the last TWO digits decide.","cta":"Watch it step by step","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn|0"},"idea-divisible-4-8-case1":{"id":"idea-divisible-4-8-case1","kind":"idea","src":"stop:divisible-4-8#case1","title":"Tests for 4 and 8: Divisible by 8","body":"A hundred does not split into eights, but a thousand does — so look at the last THREE digits. Passing the test for 4 is not enough.","more":"The method: For 4, test just the last two digits. For 8, the last three.","cta":"See it worked","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn|1"},"worked-divisible-4-8-worked1":{"id":"worked-divisible-4-8-worked1","kind":"worked","src":"stop:divisible-4-8#worked1","title":"Worked out — Tests for 4 and 8: Divisible by 8","body":"Is 73,516 divisible by 8?: The last three digits of 73,516 → 516 · Is 516 in the 8 times table? (Can you halve it three times and stay whole?) → No","more":"What is special here: A hundred does not split into eights, but a thousand does — so look at the last THREE digits. Passing the test for 4 is not enough.","cta":"Watch it step by step","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn|1"},"why-divisible-4-8-why1":{"id":"why-divisible-4-8-why1","kind":"why","src":"stop:divisible-4-8#why1","title":"Why “Tests for 4 and 8” works","body":"For 8 you need one more digit, because 100 does not divide by 8 but 1000 does: 1000 = 8 × 125. So every whole thousand divides by 8, and only the last three digits decide.","more":"The trick: For 4, test just the last two digits. For 8, the last three.","cta":"See why","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn"},"why-divisible-4-8-why2":{"id":"why-divisible-4-8-why2","kind":"why","src":"stop:divisible-4-8#why2","title":"Why “Tests for 4 and 8” works","body":"The pattern goes on: 2 needs the last digit, 4 the last two, 8 the last three — because 10 is 2 × 5, 100 is 4 × 25 and 1000 is 8 × 125.","more":"The trick: For 4, test just the last two digits. For 8, the last three.","cta":"See why","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn"},"algebra-divisible-4-8-alg":{"id":"algebra-divisible-4-8-alg","kind":"algebra","src":"stop:divisible-4-8#alg","title":"The algebra behind “Tests for 4 and 8”","body":"4 | 100 ⇒ test n mod 100 ; 8 | 1000 ⇒ test n mod 1000","more":"In words: For 4, test just the last two digits. For 8, the last three.","cta":"See why","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|learn"},"moment-divisible-4-8-beat3":{"id":"moment-divisible-4-8-beat3","kind":"moment","src":"story:divisible-4-8#beat3","badge":{"id":"story","label":"A story"},"title":"The seed packets — on the notepad","body":"Rafi: 16 is four fours. So yes, it splits exactly. 16 ÷ 4 = 4","more":"The trick in the story: For 4, test just the last two digits. For 8, the last three.","cta":"Read the story","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|story|3"},"moral-divisible-4-8-beat5":{"id":"moral-divisible-4-8-beat5","kind":"moral","src":"story:divisible-4-8#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The seed packets”","body":"And 73,516 in packets of 4 makes…","more":"The trick in the story: For 4, test just the last two digits. For 8, the last three.","cta":"Read the story","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/divisible-4-8|story|5"},"try-divisible-4-8-L5":{"id":"try-divisible-4-8-L5","kind":"try","level":5,"src":"try:divisible-4-8@5/1#0","title":"Tests for 4 and 8 — your turn","where":"The Factor Forest · Level 5","route":"#/stop/divisible-4-8|drill","cta":"Practise this stop","play":{"q":"Is 57,708 divisible by 4?","opts":["Yes","No"],"after":"For 4, test just the last two digits. For 8, the last three."}},"trick-prime-or-not-idea":{"id":"trick-prime-or-not-idea","kind":"trick","src":"stop:prime-or-not#idea","title":"Is it prime?","body":"Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime. A prime has exactly two factors: 1 and itself. 7 is prime — seven dots only make one rectangle, a single row. 1 is not prime, because it has only one factor.","more":"In algebra: n is prime ⇔ n > 1 and no prime p ≤ √n divides n","cta":"Learn the trick","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn"},"story-prime-or-not-open":{"id":"story-prime-or-not-open","kind":"story","src":"story:prime-or-not#open","badge":{"id":"story","label":"A story"},"title":"The sieve","body":"On a camping night, Theo asks Vesper: is 91 prime? It is odd, it does not end in 5, and its digits add to 10. — with Vesper and Theo.","more":"The trick inside: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","art":"art/s-night.webp","cta":"Read the story","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|story|0"},"hook-prime-or-not-hook":{"id":"hook-prime-or-not-hook","kind":"hook","src":"stop:prime-or-not#hook","title":"Can you? — Is it prime?","body":"91 — odd, does not end in 5, digits do not add to a multiple of 3. Prime?","more":"The way in: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"Find out how","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn"},"idea-prime-or-not-case0":{"id":"idea-prime-or-not-case0","kind":"idea","src":"stop:prime-or-not#case0","title":"Is it prime?: Not prime","body":"As soon as one prime divides it exactly, you can stop: it is not prime. 91 looks prime, but 7 goes in.","more":"The method: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"See it worked","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn|0"},"worked-prime-or-not-worked0":{"id":"worked-prime-or-not-worked0","kind":"worked","src":"stop:prime-or-not#worked0","title":"Worked out — Is it prime?: Not prime","body":"Is 91 prime?: Which whole number, times itself, is the last one at or below 91? Test only up to it → 9 · The smallest number bigger than 1 that divides 91 exactly → 7 · 7 divides it — so is it prime? → Not prime","more":"What is special here: As soon as one prime divides it exactly, you can stop: it is not prime. 91 looks prime, but 7 goes in.","cta":"Watch it step by step","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn|0"},"idea-prime-or-not-case1":{"id":"idea-prime-or-not-case1","kind":"idea","src":"stop:prime-or-not#case1","title":"Is it prime?: Prime","body":"To say \"prime\" you must try EVERY prime up to the square-root line and see each one fail. For 97 that is 2, 3, 5 and 7.","more":"The method: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"See it worked","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn|1"},"why-prime-or-not-why1":{"id":"why-prime-or-not-why1","kind":"why","src":"stop:prime-or-not#why1","title":"Why “Is it prime?” works","body":"Factors come in pairs that meet in the middle, so if a number has a factor bigger than its square root, the partner is smaller than it — and you would already have found the partner. For 91 you only need to try up to 9, because 10 × 10 is already 100. And 7 × 13 = 91, so 91 is not prime.","more":"The trick: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"See why","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn"},"why-prime-or-not-why2":{"id":"why-prime-or-not-why2","kind":"why","src":"stop:prime-or-not#why2","title":"Why “Is it prime?” works","body":"You only need to try primes, because any other number is built from primes: if 6 divided 91, then 2 would too. This is the idea of the Sieve: write out the numbers, cross out every multiple of 2, then of 3, then of 5, of 7… Whatever is never crossed out is prime.","more":"The trick: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"See why","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn"},"algebra-prime-or-not-alg":{"id":"algebra-prime-or-not-alg","kind":"algebra","src":"stop:prime-or-not#alg","title":"The algebra behind “Is it prime?”","body":"n is prime ⇔ n > 1 and no prime p ≤ √n divides n","more":"In words: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"See why","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|learn"},"moment-prime-or-not-beat3":{"id":"moment-prime-or-not-beat3","kind":"moment","src":"story:prime-or-not#beat3","badge":{"id":"story","label":"A story"},"title":"The sieve — on the notepad","body":"Theo: Seven thirteens… that’s 91! 7 × 13 = 91","more":"The trick in the story: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"Read the story","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|story|3"},"moral-prime-or-not-beat5":{"id":"moral-prime-or-not-beat5","kind":"moral","src":"story:prime-or-not#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The sieve”","body":"Next time I’ll try every prime up to there, and check them all.","more":"The trick in the story: Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime.","cta":"Read the story","where":"The Factor Forest · Level 5","level":5,"route":"#/stop/prime-or-not|story|5"},"try-prime-or-not-L5":{"id":"try-prime-or-not-L5","kind":"try","level":5,"src":"try:prime-or-not@5/1#0","title":"Is it prime? — your turn","where":"The Factor Forest · Level 5","route":"#/stop/prime-or-not|drill","cta":"Practise this stop","play":{"q":"Is 16 prime?","opts":["Not prime","Prime"],"after":"Try dividing by the primes 2, 3, 5, 7… but only up to the number whose square passes it. If none divides, it is prime."}},"trick-square-five-idea":{"id":"trick-square-five-idea","kind":"trick","src":"stop:square-five#idea","title":"Squaring numbers that end in 5","body":"Take the front digit, multiply it by the next number up, and write 25 on the end. 35 × 35: the front digit is 3, one more than it is 4, and 3 × 4 = 12. Write 25 after it: 1225.","more":"In algebra: (10n + 5)² = 100·n(n + 1) + 25","cta":"Learn the trick","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|learn"},"story-square-five-open":{"id":"story-square-five-open","kind":"story","src":"story:square-five#open","badge":{"id":"story","label":"A story"},"title":"Mira's square flowerbed","body":"Mira is planting a square flowerbed: 35 bulbs along each side. — with Mira and Dax.","more":"The trick inside: Take the front digit, multiply it by the next number up, and write 25 on the end.","art":"art/s-garden.webp","cta":"Read the story","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|story|0"},"hook-square-five-hook":{"id":"hook-square-five-hook","kind":"hook","src":"stop:square-five#hook","title":"Can you? — Squaring numbers that end in 5","body":"35 × 35 — in your head, in three seconds.","more":"The way in: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"Find out how","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|learn"},"worked-square-five-worked0":{"id":"worked-square-five-worked0","kind":"worked","src":"stop:square-five#worked0","title":"Worked out — Squaring numbers that end in 5","body":"35²: 3 × 4 → 12 · Write 25 on the end → 1225","more":"The method: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"Watch it step by step","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|learn|0"},"why-square-five-why1":{"id":"why-square-five-why1","kind":"why","src":"stop:square-five#why1","title":"Why “Squaring numbers that end in 5” works","body":"It works for every number ending in 5, always. A number ending in 5 is ten lots of something, plus 5. Square it and the middle always lands exactly on a whole number of hundreds — n lots of (n + 1) hundreds — and the 5 × 5 on the end is always 25.","more":"The trick: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"See why","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|learn"},"algebra-square-five-alg":{"id":"algebra-square-five-alg","kind":"algebra","src":"stop:square-five#alg","title":"The algebra behind “Squaring numbers that end in 5”","body":"(10n + 5)² = 100·n(n + 1) + 25","more":"In words: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"See why","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|learn"},"sutra-square-five-sutra":{"id":"sutra-square-five-sutra","kind":"sutra","src":"stop:square-five#sutra","title":"Ekādhikena Pūrvena","body":"“by one more than the one before” — the sutra behind Squaring numbers that end in 5.","more":"What it does: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"Open the stop","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|learn"},"moment-square-five-beat2":{"id":"moment-square-five-beat2","kind":"moment","src":"story:square-five#beat2","badge":{"id":"story","label":"A story"},"title":"Mira's square flowerbed — on the notepad","body":"Mira: No need. The front digit is 3, and one more than 3 is 4. 3 × 4 = 12","more":"The trick in the story: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"Read the story","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|story|2"},"moral-square-five-beat5":{"id":"moral-square-five-beat5","kind":"moral","src":"story:square-five#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “Mira's square flowerbed”","body":"For every number that ends in 5. The Observatory will show you why.","more":"The trick in the story: Take the front digit, multiply it by the next number up, and write 25 on the end.","cta":"Read the story","where":"The Sutra Observatory · Level 5","level":5,"route":"#/stop/square-five|story|5"},"try-square-five-L5":{"id":"try-square-five-L5","kind":"try","level":5,"src":"try:square-five@5/1#0","title":"Squaring numbers that end in 5 — your turn","where":"The Sutra Observatory · Level 5","route":"#/stop/square-five|drill","cta":"Practise this stop","play":{"q":"65² = ?","opts":["4225","42","4226"],"after":"Take the front digit, multiply it by the next number up, and write 25 on the end."}},"trick-square-dots-idea":{"id":"trick-square-dots-idea","kind":"trick","src":"stop:square-dots#idea","title":"What a square number is","body":"n² means n rows of n. Lay them out and they make a perfect square. Put 7 counters in a row, then make 7 rows like it. The shape is exactly as tall as it is wide: a square. There are 7 × 7 = 49 counters, so 49 is a square number, and we write 7 × 7 as 7² — \"seven squared\".","more":"In algebra: n² = n × n","cta":"Learn the trick","where":"The Square Palace · Level 5","level":5,"route":"#/stop/square-dots|learn"},"story-square-dots-open":{"id":"story-square-dots-open","kind":"story","src":"story:square-dots#open","badge":{"id":"story","label":"A story"},"title":"The parade ground","body":"Morning at the Square Palace. The guards line up on the parade ground: 7 rows, 7 guards in every row. — with Mira and Pip.","more":"The trick inside: n² means n rows of n. Lay them out and they make a perfect square.","art":"art/s-palace.webp","cta":"Read the story","where":"The Square Palace · Level 5","level":5,"route":"#/stop/square-dots|story|0"},"worked-square-dots-worked0":{"id":"worked-square-dots-worked0","kind":"worked","src":"stop:square-dots#worked0","title":"Worked out — What a square number is","body":"7²: Dots in each row → 7 · How many rows? → 7 · 7 rows of 7 → 49","more":"The method: n² means n rows of n. Lay them out and they make a perfect square.","cta":"Watch it step by step","where":"The Square Palace · Level 5","level":5,"route":"#/stop/square-dots|learn|0"},"why-square-dots-why2":{"id":"why-square-dots-why2","kind":"why","src":"stop:square-dots#why2","title":"Why “What a square number is” works","body":"The little 2 means \"two of them multiplied\": 7² is 7 × 7, not 7 × 2. Knowing the squares up to 20 by heart is worth it — every trick in this palace starts from them.","more":"The trick: n² means n rows of n. Lay them out and they make a perfect square.","cta":"See why","where":"The Square Palace · Level 5","level":5,"route":"#/stop/square-dots|learn"},"moment-square-dots-beat3":{"id":"moment-square-dots-beat3","kind":"moment","src":"story:square-dots#beat3","badge":{"id":"story","label":"A story"},"title":"The parade ground — on the notepad","body":"Pip: Then when the band joins, 8 rows of 8 is a bigger square! 8 × 8 = 64","more":"The trick in the story: n² means n rows of n. Lay them out and they make a perfect square.","cta":"Read the story","where":"The Square Palace · Level 5","level":5,"route":"#/stop/square-dots|story|3"},"try-square-dots-L5":{"id":"try-square-dots-L5","kind":"try","level":5,"src":"try:square-dots@5/1#0","title":"What a square number is — your turn","where":"The Square Palace · Level 5","route":"#/stop/square-dots|drill","cta":"Practise this stop","play":{"q":"2² = ?","opts":["4","2","5"],"after":"n² means n rows of n. Lay them out and they make a perfect square."}},"trick-powers-index-idea":{"id":"trick-powers-index-idea","kind":"trick","src":"stop:powers-index#idea","title":"Powers: the little number","body":"The little raised number (the index) says how many of the big number to multiply together. 2⁵ means 2 × 2 × 2 × 2 × 2. Squared was the index 2; cubed is the index 3; the index can be anything. Work along: 2, 4, 8, 16, 32.","more":"In algebra: aⁿ = a × a × … × a  (n of them)   ·   a²ᵏ = aᵏ × aᵏ","cta":"Learn the trick","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn"},"story-powers-index-open":{"id":"story-powers-index-open","kind":"story","src":"story:powers-index#open","badge":{"id":"story","label":"A story"},"title":"The doubling rice","body":"Pip finds an old board game in the palace attic. Put 1 grain on the first square, then double it on each square after. — with Vesper and Pip.","more":"The trick inside: The little raised number (the index) says how many of the big number to multiply together.","art":"art/s-room.webp","cta":"Read the story","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|story|0"},"hook-powers-index-hook":{"id":"hook-powers-index-hook","kind":"hook","src":"stop:powers-index#hook","title":"Can you? — Powers: the little number","body":"2⁵ — five twos, multiplied.","more":"The way in: The little raised number (the index) says how many of the big number to multiply together.","cta":"Find out how","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn"},"idea-powers-index-case0":{"id":"idea-powers-index-case0","kind":"idea","src":"stop:powers-index#case0","title":"Powers: the little number: Multiply along","body":"A small index: just keep multiplying by the big number, one step for each.","more":"The method: The little raised number (the index) says how many of the big number to multiply together.","cta":"See it worked","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn|0"},"worked-powers-index-worked0":{"id":"worked-powers-index-worked0","kind":"worked","src":"stop:powers-index#worked0","title":"Worked out — Powers: the little number: Multiply along","body":"2⁵: How many 2s are multiplied? → 5 · 2 × 2 → 4 · 4 × 2 → 8 · 8 × 2 → 16 · 16 × 2 → 32","more":"What is special here: A small index: just keep multiplying by the big number, one step for each.","cta":"Watch it step by step","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn|0"},"idea-powers-index-case1":{"id":"idea-powers-index-case1","kind":"idea","src":"stop:powers-index#case1","title":"Powers: the little number: A big index: halve it","body":"Too many to multiply one by one. Work out half the power, then multiply it by itself (and by one more if the index is odd).","more":"The method: The little raised number (the index) says how many of the big number to multiply together.","cta":"See it worked","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn|1"},"worked-powers-index-worked1":{"id":"worked-powers-index-worked1","kind":"worked","src":"stop:powers-index#worked1","title":"Worked out — Powers: the little number: A big index: halve it","body":"3⁷: How many 3s are multiplied? → 7 · Half the index: 3³ → 27 · 27 × 27 → 729 · One more × 3 → 2187","more":"What is special here: Too many to multiply one by one. Work out half the power, then multiply it by itself (and by one more if the index is odd).","cta":"Watch it step by step","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn|1"},"idea-powers-index-case2":{"id":"idea-powers-index-case2","kind":"idea","src":"stop:powers-index#case2","title":"Powers: the little number: Doubling from 1","body":"Doubling again and again is a power of 2 in words: double 8 times is 2 to the power 8.","more":"The method: The little raised number (the index) says how many of the big number to multiply together.","cta":"See it worked","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn|2"},"worked-powers-index-worked2":{"id":"worked-powers-index-worked2","kind":"worked","src":"stop:powers-index#worked2","title":"Worked out — Powers: the little number: Doubling from 1","body":"Start at 1 and double 8 times: How many 2s are multiplied? → 8 · Half the index: 2⁴ → 16 · 16 × 16 → 256","more":"What is special here: Doubling again and again is a power of 2 in words: double 8 times is 2 to the power 8.","cta":"Watch it step by step","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn|2"},"why-powers-index-why1":{"id":"why-powers-index-why1","kind":"why","src":"stop:powers-index#why1","title":"Why “Powers: the little number” works","body":"Powers grow astonishingly fast, because each step multiplies what you already have. A pond weed that doubles every day covers 2 patches on day one, then 4, 8, 16… after only 20 doublings it is over a million. That is called exponential growth.","more":"The trick: The little raised number (the index) says how many of the big number to multiply together.","cta":"See why","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn"},"why-powers-index-why2":{"id":"why-powers-index-why2","kind":"why","src":"stop:powers-index#why2","title":"Why “Powers: the little number” works","body":"For a big index, split it in half: 2¹⁰ is 2⁵ × 2⁵ = 32 × 32 = 1024. Two halves of the same power multiplied together make the whole power.","more":"The trick: The little raised number (the index) says how many of the big number to multiply together.","cta":"See why","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn"},"algebra-powers-index-alg":{"id":"algebra-powers-index-alg","kind":"algebra","src":"stop:powers-index#alg","title":"The algebra behind “Powers: the little number”","body":"aⁿ = a × a × … × a  (n of them)   ·   a²ᵏ = aᵏ × aᵏ","more":"In words: The little raised number (the index) says how many of the big number to multiply together.","cta":"See why","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|learn"},"moment-powers-index-beat4":{"id":"moment-powers-index-beat4","kind":"moment","src":"story:powers-index#beat4","badge":{"id":"story","label":"A story"},"title":"The doubling rice — on the notepad","body":"Vesper: No. Two lots of five doublings, one after the other. 32 × 32 = 1024","more":"The trick in the story: The little raised number (the index) says how many of the big number to multiply together.","cta":"Read the story","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|story|4"},"moral-powers-index-beat5":{"id":"moral-powers-index-beat5","kind":"moral","src":"story:powers-index#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The doubling rice”","body":"Over a thousand! The little number, the power, says how many twos. 2 to the power 5 is thirty-two.","more":"The trick in the story: The little raised number (the index) says how many of the big number to multiply together.","cta":"Read the story","where":"The Square Palace · Level 5","level":5,"route":"#/stop/powers-index|story|5"},"try-powers-index-L5":{"id":"try-powers-index-L5","kind":"try","level":5,"src":"try:powers-index@5/1#0","title":"Powers: the little number — your turn","where":"The Square Palace · Level 5","route":"#/stop/powers-index|drill","cta":"Practise this stop","play":{"q":"10³ = ?","opts":["1000","3","100"],"after":"The little raised number (the index) says how many of the big number to multiply together."}},"trick-add-decimals-idea":{"id":"trick-add-decimals-idea","kind":"trick","src":"stop:add-decimals#idea","title":"Line up the point","body":"Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers. You can only add things of the same kind: ones to ones, tenths to tenths. Writing 3.5 and 1.27 with their points in a column puts every digit under a digit of the same value.","more":"In algebra: a + b = (a × 10ᵈ + b × 10ᵈ) ÷ 10ᵈ, d = the most decimal places","cta":"Learn the trick","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn"},"story-add-decimals-open":{"id":"story-add-decimals-open","kind":"story","src":"story:add-decimals#open","badge":{"id":"story","label":"A story"},"title":"Two bags of shopping","body":"Nova buys bread for 3.5 coins and cheese for 1.27 coins. — with Theo and Nova.","more":"The trick inside: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","art":"art/s-shop.webp","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|story|0"},"hook-add-decimals-hook":{"id":"hook-add-decimals-hook","kind":"hook","src":"stop:add-decimals#hook","title":"Can you? — Line up the point","body":"3.5 + 1.27 — why is it not 1.62?","more":"The way in: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"Find out how","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn"},"idea-add-decimals-case0":{"id":"idea-add-decimals-case0","kind":"idea","src":"stop:add-decimals#case0","title":"Line up the point: Add, same places","body":"Both have tenths only, so the points already line up. Add the tenths as whole numbers, then put the point back.","more":"The method: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|0"},"worked-add-decimals-worked0":{"id":"worked-add-decimals-worked0","kind":"worked","src":"stop:add-decimals#worked0","title":"Worked out — Line up the point: Add, same places","body":"2.4 + 1.8: 2.4 in tenths → 24 · 1.8 in tenths → 18 · Add the tenths → 42 · Back to a decimal: ÷ 10 → 4.2","more":"What is special here: Both have tenths only, so the points already line up. Add the tenths as whole numbers, then put the point back.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|0"},"idea-add-decimals-case1":{"id":"idea-add-decimals-case1","kind":"idea","src":"stop:add-decimals#case1","title":"Line up the point: Add, different places","body":"One number has hundredths and the other does not. Turn both into hundredths first, so tenths add to tenths.","more":"The method: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|1"},"worked-add-decimals-worked1":{"id":"worked-add-decimals-worked1","kind":"worked","src":"stop:add-decimals#worked1","title":"Worked out — Line up the point: Add, different places","body":"3.5 + 1.27: 3.5 in hundredths → 350 · 1.27 in hundredths → 127 · Add the hundredths → 477 · Back to a decimal: ÷ 100 → 4.77","more":"What is special here: One number has hundredths and the other does not. Turn both into hundredths first, so tenths add to tenths.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|1"},"idea-add-decimals-case2":{"id":"idea-add-decimals-case2","kind":"idea","src":"stop:add-decimals#case2","title":"Line up the point: Take away, same places","body":"Line up the points and take tenths from tenths, just like whole numbers.","more":"The method: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|2"},"worked-add-decimals-worked2":{"id":"worked-add-decimals-worked2","kind":"worked","src":"stop:add-decimals#worked2","title":"Worked out — Line up the point: Take away, same places","body":"5.2 − 3.7: 5.2 in tenths → 52 · 3.7 in tenths → 37 · Take away the tenths → 15 · Back to a decimal: ÷ 10 → 1.5","more":"What is special here: Line up the points and take tenths from tenths, just like whole numbers.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|2"},"idea-add-decimals-case3":{"id":"idea-add-decimals-case3","kind":"idea","src":"stop:add-decimals#case3","title":"Line up the point: Take away, different places","body":"The shorter number gets a zero in its empty place — 5.2 is 520 hundredths — then take away as whole numbers.","more":"The method: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|3"},"worked-add-decimals-worked3":{"id":"worked-add-decimals-worked3","kind":"worked","src":"stop:add-decimals#worked3","title":"Worked out — Line up the point: Take away, different places","body":"5.2 − 1.45: 5.2 in hundredths → 520 · 1.45 in hundredths → 145 · Take away the hundredths → 375 · Back to a decimal: ÷ 100 → 3.75","more":"What is special here: The shorter number gets a zero in its empty place — 5.2 is 520 hundredths — then take away as whole numbers.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn|3"},"why-add-decimals-why1":{"id":"why-add-decimals-why1","kind":"why","src":"stop:add-decimals#why1","title":"Why “Line up the point” works","body":"The 5 in 3.5 is 5 tenths, which is 50 hundredths. So 3.5 is 350 hundredths and 1.27 is 127 hundredths. Now it is a sum of whole numbers: 477 hundredths, which is 4.77. Taking away works the same way: 5.2 − 1.45 is 520 − 145 = 375 hundredths, 3.75. The empty place in 5.2 is a zero, not a gap to skip.","more":"The trick: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn"},"why-add-decimals-why2":{"id":"why-add-decimals-why2","kind":"why","src":"stop:add-decimals#why2","title":"Why “Line up the point” works","body":"Adding 5 and 27 as if they were the same kind of thing (to get 1.62) is adding tenths to hundredths — like adding 5 metres to 27 centimetres and calling it 32. Lining up the point is what stops it.","more":"The trick: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn"},"algebra-add-decimals-alg":{"id":"algebra-add-decimals-alg","kind":"algebra","src":"stop:add-decimals#alg","title":"The algebra behind “Line up the point”","body":"a + b = (a × 10ᵈ + b × 10ᵈ) ÷ 10ᵈ, d = the most decimal places","more":"In words: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|learn"},"moment-add-decimals-beat4":{"id":"moment-add-decimals-beat4","kind":"moment","src":"story:add-decimals#beat4","badge":{"id":"story","label":"A story"},"title":"Two bags of shopping — on the notepad","body":"Nova: 477 hundredths. Back to coins… 477 ÷ 100 = 4.77","more":"The trick in the story: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|story|4"},"moral-add-decimals-beat5":{"id":"moral-add-decimals-beat5","kind":"moral","src":"story:add-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “Two bags of shopping”","body":"4.77 coins. Tenths under tenths, every time.","more":"The trick in the story: Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/add-decimals|story|5"},"try-add-decimals-L5":{"id":"try-add-decimals-L5","kind":"try","level":5,"src":"try:add-decimals@5/1#0","title":"Line up the point — your turn","where":"The Decimal Dock · Level 5","route":"#/stop/add-decimals|drill","cta":"Practise this stop","play":{"q":"4.5 + 8.8 = ?","opts":["13.3","45","88"],"after":"Line the points up so tenths add to tenths — or turn both into hundredths and add whole numbers."}},"trick-round-decimals-idea":{"id":"trick-round-decimals-idea","kind":"trick","src":"stop:round-decimals#idea","title":"Rounding decimals","body":"Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up. Rounding asks which of two neighbours a number is nearer. To one decimal place, 12.68 sits between 12.6 and 12.7 on the number line.","more":"In algebra: round x to d places: look at digit d + 1; ≥ 5 → up, < 5 → stay","cta":"Learn the trick","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn"},"story-round-decimals-open":{"id":"story-round-decimals-open","kind":"story","src":"story:round-decimals#open","badge":{"id":"story","label":"A story"},"title":"The longest fish","body":"On the beach, Dax measures a piece of driftwood: 12.68 metres of rope would go round it. — with Suki and Dax.","more":"The trick inside: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","art":"art/s-beach.webp","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|story|0"},"hook-round-decimals-hook":{"id":"hook-round-decimals-hook","kind":"hook","src":"stop:round-decimals#hook","title":"Can you? — Rounding decimals","body":"12.68 m of rope — about how much, to one decimal place?","more":"The way in: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"Find out how","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn"},"idea-round-decimals-case0":{"id":"idea-round-decimals-case0","kind":"idea","src":"stop:round-decimals#case0","title":"Rounding decimals: To a whole number: stay","body":"Cut it off after the ones. The next digit is under 5, so the number is in the first half of the gap — it stays.","more":"The method: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|0"},"worked-round-decimals-worked0":{"id":"worked-round-decimals-worked0","kind":"worked","src":"stop:round-decimals#worked0","title":"Worked out — Rounding decimals: To a whole number: stay","body":"Round 7.3 to the nearest whole number: Cut it off after the ones → 7 · The very next digit → 3 · 5 or more goes up; 4 or less stays → 7","more":"What is special here: Cut it off after the ones. The next digit is under 5, so the number is in the first half of the gap — it stays.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|0"},"idea-round-decimals-case1":{"id":"idea-round-decimals-case1","kind":"idea","src":"stop:round-decimals#case1","title":"Rounding decimals: To a whole number: up","body":"The next digit is 5 — exactly halfway — and halfway always rounds up.","more":"The method: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|1"},"idea-round-decimals-case2":{"id":"idea-round-decimals-case2","kind":"idea","src":"stop:round-decimals#case2","title":"Rounding decimals: To decimal places: up","body":"Cut it off after the places you want. An 8 next means you are most of the way to the next one up.","more":"The method: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|2"},"worked-round-decimals-worked2":{"id":"worked-round-decimals-worked2","kind":"worked","src":"stop:round-decimals#worked2","title":"Worked out — Rounding decimals: To decimal places: up","body":"Round 12.68 to 1 decimal place: Cut it off after 1 decimal place → 12.6 · The very next digit → 8 · 5 or more goes up; 4 or less stays → 12.7","more":"What is special here: Cut it off after the places you want. An 8 next means you are most of the way to the next one up.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|2"},"idea-round-decimals-case3":{"id":"idea-round-decimals-case3","kind":"idea","src":"stop:round-decimals#case3","title":"Rounding decimals: To decimal places: stay","body":"The next digit is under 5, so you stay — and the digits after it cannot pull you over halfway.","more":"The method: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|3"},"worked-round-decimals-worked3":{"id":"worked-round-decimals-worked3","kind":"worked","src":"stop:round-decimals#worked3","title":"Worked out — Rounding decimals: To decimal places: stay","body":"Round 4.329 to 1 decimal place: Cut it off after 1 decimal place → 4.3 · The very next digit → 2 · 5 or more goes up; 4 or less stays → 4.3","more":"What is special here: The next digit is under 5, so you stay — and the digits after it cannot pull you over halfway.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn|3"},"why-round-decimals-why1":{"id":"why-round-decimals-why1","kind":"why","src":"stop:round-decimals#why1","title":"Why “Rounding decimals” works","body":"The digit just after where you stop tells you how far along the gap you are. An 8 means eight tenths of the way from 12.6 to 12.7 — much nearer 12.7. A digit under 5 means you are in the first half, so you stay.","more":"The trick: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn"},"why-round-decimals-why2":{"id":"why-round-decimals-why2","kind":"why","src":"stop:round-decimals#why2","title":"Why “Rounding decimals” works","body":"Exactly 5 is exactly halfway, and the rule everyone agrees on is to round it up — so a number never has to argue about which side it belongs to. Only the one next digit counts; the digits after it cannot pull you back over halfway.","more":"The trick: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn"},"algebra-round-decimals-alg":{"id":"algebra-round-decimals-alg","kind":"algebra","src":"stop:round-decimals#alg","title":"The algebra behind “Rounding decimals”","body":"round x to d places: look at digit d + 1; ≥ 5 → up, < 5 → stay","more":"In words: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|learn"},"moment-round-decimals-beat4":{"id":"moment-round-decimals-beat4","kind":"moment","src":"story:round-decimals#beat4","badge":{"id":"story","label":"A story"},"title":"The longest fish — on the notepad","body":"Dax: Five or more goes up. So about 12.7 metres. 12.6 + 0.1 = 12.7","more":"The trick in the story: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|story|4"},"moral-round-decimals-beat5":{"id":"moral-round-decimals-beat5","kind":"moral","src":"story:round-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The longest fish”","body":"And to the nearest whole metre, the 6 decides: 13.","more":"The trick in the story: Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/round-decimals|story|5"},"try-round-decimals-L5":{"id":"try-round-decimals-L5","kind":"try","level":5,"src":"try:round-decimals@5/1#0","title":"Rounding decimals — your turn","where":"The Decimal Dock · Level 5","route":"#/stop/round-decimals|drill","cta":"Practise this stop","play":{"q":"Round 13.5 to the nearest whole number = ?","opts":["14","13","5"],"after":"Cut the number where you want to stop, then look at the very next digit: 5 or more rounds up."}},"trick-fraction-decimal-percent-idea":{"id":"trick-fraction-decimal-percent-idea","kind":"trick","src":"stop:fraction-decimal-percent#idea","title":"Fractions, decimals, per cents","body":"Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths. Per cent means \"out of a hundred\" (cent is the old word for hundred, as in century). So 75% is just another way to write 75/100.","more":"In algebra: a/b = (a × 100/b)/100 = (a × 100/b)% ","cta":"Learn the trick","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn"},"story-fraction-decimal-percent-open":{"id":"story-fraction-decimal-percent-open","kind":"story","src":"story:fraction-decimal-percent#open","badge":{"id":"story","label":"A story"},"title":"Three signs, one discount","body":"Three shops on the high street. One sign says 3/4 of the price. One says 0.75 of the price. One says 75%. — with Ines and Pip.","more":"The trick inside: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","art":"art/s-shop.webp","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|story|0"},"hook-fraction-decimal-percent-hook":{"id":"hook-fraction-decimal-percent-hook","kind":"hook","src":"stop:fraction-decimal-percent#hook","title":"Can you? — Fractions, decimals, per cents","body":"3/4, 0.75 and 75% — are those three different numbers?","more":"The way in: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"Find out how","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn"},"idea-fraction-decimal-percent-case0":{"id":"idea-fraction-decimal-percent-case0","kind":"idea","src":"stop:fraction-decimal-percent#case0","title":"Fractions, decimals, per cents: Fraction to decimal","body":"Make the bottom 100 with an equivalent fraction. The hundredths are the two places after the point.","more":"The method: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|0"},"worked-fraction-decimal-percent-worked0":{"id":"worked-fraction-decimal-percent-worked0","kind":"worked","src":"stop:fraction-decimal-percent#worked0","title":"Worked out — Fractions, decimals, per cents: Fraction to decimal","body":"3/4 as a decimal: 3/4 = ?/100 → 75 · hundredths as a decimal → 0.75","more":"What is special here: Make the bottom 100 with an equivalent fraction. The hundredths are the two places after the point.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|0"},"idea-fraction-decimal-percent-case1":{"id":"idea-fraction-decimal-percent-case1","kind":"idea","src":"stop:fraction-decimal-percent#case1","title":"Fractions, decimals, per cents: Decimal to percentage","body":"Read the decimal as hundredths — and per cent means hundredths, so that is the percentage.","more":"The method: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|1"},"worked-fraction-decimal-percent-worked1":{"id":"worked-fraction-decimal-percent-worked1","kind":"worked","src":"stop:fraction-decimal-percent#worked1","title":"Worked out — Fractions, decimals, per cents: Decimal to percentage","body":"0.36 as a percentage: 0.36 is how many hundredths? → 36 · Per cent means hundredths → 36","more":"What is special here: Read the decimal as hundredths — and per cent means hundredths, so that is the percentage.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|1"},"idea-fraction-decimal-percent-case2":{"id":"idea-fraction-decimal-percent-case2","kind":"idea","src":"stop:fraction-decimal-percent#case2","title":"Fractions, decimals, per cents: Percentage to fraction","body":"Write it over 100, then simplify by dividing top and bottom by the same number.","more":"The method: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|2"},"worked-fraction-decimal-percent-worked2":{"id":"worked-fraction-decimal-percent-worked2","kind":"worked","src":"stop:fraction-decimal-percent#worked2","title":"Worked out — Fractions, decimals, per cents: Percentage to fraction","body":"35% as a fraction: 35% = ?/100 → 35 · Divide top and bottom by → 5 · The fraction → 7/20","more":"What is special here: Write it over 100, then simplify by dividing top and bottom by the same number.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|2"},"idea-fraction-decimal-percent-case3":{"id":"idea-fraction-decimal-percent-case3","kind":"idea","src":"stop:fraction-decimal-percent#case3","title":"Fractions, decimals, per cents: Fraction to percentage","body":"Make the bottom 100, and the top IS the percentage.","more":"The method: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|3"},"worked-fraction-decimal-percent-worked3":{"id":"worked-fraction-decimal-percent-worked3","kind":"worked","src":"stop:fraction-decimal-percent#worked3","title":"Worked out — Fractions, decimals, per cents: Fraction to percentage","body":"2/5 as a percentage: 2/5 = ?/100 → 40 · Hundredths are per cent → 40","more":"What is special here: Make the bottom 100, and the top IS the percentage.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|3"},"idea-fraction-decimal-percent-case4":{"id":"idea-fraction-decimal-percent-case4","kind":"idea","src":"stop:fraction-decimal-percent#case4","title":"Fractions, decimals, per cents: Decimal via thousandths","body":"Eighths do not go into 100, but they do go into 1000. Thousandths are three places after the point.","more":"The method: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|4"},"worked-fraction-decimal-percent-worked4":{"id":"worked-fraction-decimal-percent-worked4","kind":"worked","src":"stop:fraction-decimal-percent#worked4","title":"Worked out — Fractions, decimals, per cents: Decimal via thousandths","body":"3/8 as a decimal: 3/8 = ?/1000 → 375 · thousandths as a decimal → 0.375","more":"What is special here: Eighths do not go into 100, but they do go into 1000. Thousandths are three places after the point.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|4"},"idea-fraction-decimal-percent-case5":{"id":"idea-fraction-decimal-percent-case5","kind":"idea","src":"stop:fraction-decimal-percent#case5","title":"Fractions, decimals, per cents: Percentage via thousandths","body":"Make the bottom 1000, then divide by 10 to get hundredths — per cent can have a decimal too.","more":"The method: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|5"},"worked-fraction-decimal-percent-worked5":{"id":"worked-fraction-decimal-percent-worked5","kind":"worked","src":"stop:fraction-decimal-percent#worked5","title":"Worked out — Fractions, decimals, per cents: Percentage via thousandths","body":"3/8 as a percentage: 3/8 = ?/1000 → 375 · ÷ 10 for per cent → 37.5","more":"What is special here: Make the bottom 1000, then divide by 10 to get hundredths — per cent can have a decimal too.","cta":"Watch it step by step","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn|5"},"why-fraction-decimal-percent-why1":{"id":"why-fraction-decimal-percent-why1","kind":"why","src":"stop:fraction-decimal-percent#why1","title":"Why “Fractions, decimals, per cents” works","body":"And 75 hundredths as a decimal is 0.75 — the second place after the point is the hundredths place. So all three are one number wearing different clothes: 3/4 = 75/100 = 0.75 = 75%.","more":"The trick: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn"},"why-fraction-decimal-percent-why2":{"id":"why-fraction-decimal-percent-why2","kind":"why","src":"stop:fraction-decimal-percent#why2","title":"Why “Fractions, decimals, per cents” works","body":"To get from a fraction to hundredths, use equivalent fractions: 3/4 = 75/100 because 4 × 25 = 100, so 3 × 25 = 75. Some fractions need thousandths instead: 3/8 = 375/1000 = 0.375.","more":"The trick: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn"},"algebra-fraction-decimal-percent-alg":{"id":"algebra-fraction-decimal-percent-alg","kind":"algebra","src":"stop:fraction-decimal-percent#alg","title":"The algebra behind “Fractions, decimals, per cents”","body":"a/b = (a × 100/b)/100 = (a × 100/b)% ","more":"In words: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|learn"},"moment-fraction-decimal-percent-beat3":{"id":"moment-fraction-decimal-percent-beat3","kind":"moment","src":"story:fraction-decimal-percent#beat3","badge":{"id":"story","label":"A story"},"title":"Three signs, one discount — on the notepad","body":"Ines: …so 3 quarters is 75 hundredths. 3 × 25 = 75","more":"The trick in the story: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|story|3"},"moral-fraction-decimal-percent-beat5":{"id":"moral-fraction-decimal-percent-beat5","kind":"moral","src":"story:fraction-decimal-percent#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Three signs, one discount”","body":"Three signs, one number. Pick the shop with the nicest cake.","more":"The trick in the story: Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/fraction-decimal-percent|story|5"},"try-fraction-decimal-percent-L5":{"id":"try-fraction-decimal-percent-L5","kind":"try","level":5,"src":"try:fraction-decimal-percent@5/1#0","title":"Fractions, decimals, per cents — your turn","where":"The Decimal Dock · Level 5","route":"#/stop/fraction-decimal-percent|drill","cta":"Practise this stop","play":{"q":"3/10 as a decimal = ?","opts":["0.3","30","0.4"],"after":"Turn the fraction into hundredths. Hundredths ARE the decimal places, and \"per cent\" means hundredths."}},"trick-percent-of-amount-idea":{"id":"trick-percent-of-amount-idea","kind":"trick","src":"stop:percent-of-amount#idea","title":"Percentages of an amount","body":"Find 10% by dividing by 10. Build everything else from 10% and its half, 5%. 10% means 10 out of every 100 — one tenth. So 10% of anything is that thing divided by 10: 10% of 60 is 6.","more":"In algebra: p% of n = (n ÷ 10) × (p ÷ 10)","cta":"Learn the trick","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn"},"story-percent-of-amount-open":{"id":"story-percent-of-amount-open","kind":"story","src":"story:percent-of-amount#open","badge":{"id":"story","label":"A story"},"title":"The harbour tax","body":"The fishing boat brought in 60 kg of fish. 35% goes to the market in town. — with Ines and Rafi.","more":"The trick inside: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","art":"art/s-harbour.webp","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|story|0"},"idea-percent-of-amount-case0":{"id":"idea-percent-of-amount-case0","kind":"idea","src":"stop:percent-of-amount#case0","title":"Percentages of an amount: Just 10%","body":"10% is one tenth, so divide by 10. Every other percentage here is built from this one.","more":"The method: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn|0"},"idea-percent-of-amount-case1":{"id":"idea-percent-of-amount-case1","kind":"idea","src":"stop:percent-of-amount#case1","title":"Percentages of an amount: Lots of 10%","body":"30% is three lots of 10%: find 10% first, then multiply by how many tens.","more":"The method: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn|1"},"idea-percent-of-amount-case2":{"id":"idea-percent-of-amount-case2","kind":"idea","src":"stop:percent-of-amount#case2","title":"Percentages of an amount: Just 5%","body":"5% is half of 10%, so find 10% and halve it.","more":"The method: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn|2"},"idea-percent-of-amount-case3":{"id":"idea-percent-of-amount-case3","kind":"idea","src":"stop:percent-of-amount#case3","title":"Percentages of an amount: Tens and a 5","body":"Split it into tens and a five: 35% is 30% and 5%. Find both, then add.","more":"The method: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"See it worked","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn|3"},"why-percent-of-amount-why1":{"id":"why-percent-of-amount-why1","kind":"why","src":"stop:percent-of-amount#why1","title":"Why “Percentages of an amount” works","body":"Other percentages are made of tens. 30% is three lots of 10%: 18. And 5% is half of 10%: 3. So 35% of 60 is 18 + 3 = 21.","more":"The trick: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn"},"algebra-percent-of-amount-alg":{"id":"algebra-percent-of-amount-alg","kind":"algebra","src":"stop:percent-of-amount#alg","title":"The algebra behind “Percentages of an amount”","body":"p% of n = (n ÷ 10) × (p ÷ 10)","more":"In words: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"See why","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|learn"},"moral-percent-of-amount-beat5":{"id":"moral-percent-of-amount-beat5","kind":"moral","src":"story:percent-of-amount#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The harbour tax”","body":"Add them up: 21 kg to the market.","more":"The trick in the story: Find 10% by dividing by 10. Build everything else from 10% and its half, 5%.","cta":"Read the story","where":"The Decimal Dock · Level 5","level":5,"route":"#/stop/percent-of-amount|story|5"},"try-percent-of-amount-L5":{"id":"try-percent-of-amount-L5","kind":"try","level":5,"src":"try:percent-of-amount@5/1#0","title":"Percentages of an amount — your turn","where":"The Decimal Dock · Level 5","route":"#/stop/percent-of-amount|drill","cta":"Practise this stop","play":{"q":"10% of 280 = ?","opts":["28","10","29"],"after":"Find 10% by dividing by 10. Build everything else from 10% and its half, 5%."}},"hook-nine-division-hook":{"id":"hook-nine-division-hook","kind":"hook","src":"stop:nine-division#hook","title":"Can you? — Dividing by 9, digit by digit","body":"1232 ÷ 9 — the answer and the remainder, with no times table at all.","more":"The way in: Keep a running total of the digits: the totals are the answer, and the total of ALL the digits is the remainder.","cta":"Find out how","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn"},"worked-nine-division-worked0":{"id":"worked-nine-division-worked0","kind":"worked","src":"stop:nine-division#worked0","title":"Worked out — Dividing by 9, digit by digit: The answer","body":"1232 ÷ 9: how many whole 9s?: Running totals: 1 | 3 | 6. Read them as one number, carrying → 136 · Add ALL the digits: the remainder column → 8 · 8 is less than 9, so nothing moves. The answer → 136","more":"What is special here: The running totals of the digits, read as one number, are the answer.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn|0"},"worked-nine-division-worked1":{"id":"worked-nine-division-worked1","kind":"worked","src":"stop:nine-division#worked1","title":"Worked out — Dividing by 9, digit by digit: The remainder","body":"2104 ÷ 9: the remainder?: Running totals: 2 | 3 | 3. Read them as one number, carrying → 233 · Add ALL the digits: the remainder column → 7","more":"What is special here: Add up every digit. While that total is under 9, it is the remainder.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn|1"},"worked-nine-division-worked2":{"id":"worked-nine-division-worked2","kind":"worked","src":"stop:nine-division#worked2","title":"Worked out — Dividing by 9, digit by digit: A nine in the total","body":"1357 ÷ 9: how many whole 9s?: Running totals: 1 | 4 | 9. Read them as one number, carrying → 149 · Add ALL the digits: the remainder column → 16 · 16 holds 1 more 9: 149 + 1 → 150","more":"What is special here: The digits add to 9 or more: that total holds another 9, so the answer goes up by one.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn|2"},"worked-nine-division-worked3":{"id":"worked-nine-division-worked3","kind":"worked","src":"stop:nine-division#worked3","title":"Worked out — Dividing by 9, digit by digit: Fixing the remainder","body":"4728 ÷ 9: the remainder?: Running totals: 4 | 11 | 13. Read them as one number, carrying → 523 · Add ALL the digits: the remainder column → 21 · 21 holds 2 more 9s: 21 − 18 → 3","more":"What is special here: The digits add to 9 or more: take out the nines, and what is left is the true remainder.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn|3"},"why-nine-division-why2":{"id":"why-nine-division-why2","kind":"why","src":"stop:nine-division#why2","title":"Why “Dividing by 9, digit by digit” works","body":"If the digit total is 9 or more, it still holds some nines. 1357: totals 1, 4, 9 make 149, and the digits add to 16. 16 is one more 9 and 7, so the answer is 150, remainder 7.","more":"The trick: Keep a running total of the digits: the totals are the answer, and the total of ALL the digits is the remainder.","cta":"See why","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn"},"sutra-nine-division-sutra":{"id":"sutra-nine-division-sutra","kind":"sutra","src":"stop:nine-division#sutra","title":"Nikhilam Navataścaramaṁ Daśataḥ","body":"“all from nine and the last from ten” — the sutra behind Dividing by 9, digit by digit.","more":"What it does: Keep a running total of the digits: the totals are the answer, and the total of ALL the digits is the remainder.","cta":"Open the stop","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|learn"},"moral-nine-division-beat5":{"id":"moral-nine-division-beat5","kind":"moral","src":"story:nine-division#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Lamps in boxes of nine”","body":"So the totals 1, 3, 6 read as 136 full boxes, with 8 lamps over.","more":"The trick in the story: Keep a running total of the digits: the totals are the answer, and the total of ALL the digits is the remainder.","cta":"Read the story","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/nine-division|story|5"},"try-nine-division-L5":{"id":"try-nine-division-L5","kind":"try","level":5,"src":"try:nine-division@5/2#0","title":"Dividing by 9, digit by digit — your turn","where":"The Sutra Ladder · Level 5","route":"#/stop/nine-division|drill","cta":"Practise this stop","play":{"q":"207 ÷ 9: the remainder?","opts":["0","22","9"],"after":"Keep a running total of the digits: the totals are the answer, and the total of ALL the digits is the remainder."}},"trick-base-division-idea":{"id":"trick-base-division-idea","kind":"trick","src":"stop:base-division#idea","title":"Dividing near a base","body":"Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end. 2391 ÷ 98. 98 is 2 short of 100, so every hundred holds one 98 with 2 spare. 2391 is 23 hundreds and 91. The 23 hundreds give 23 nines-and-eights — 23 lots of 98 — and 23 × 2 = 46 spare.","more":"In algebra: N = a·B + b = a·(B − c) + (a·c + b),  so  N ÷ (B − c) = a, remainder a·c + b (if that is less than B − c)","cta":"Learn the trick","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn"},"story-base-division-open":{"id":"story-base-division-open","kind":"story","src":"story:base-division#open","badge":{"id":"story","label":"A story"},"title":"Carriages of ninety-eight","body":"The hill train has carriages of 98 seats, and 2391 people are booked. How many carriages are completely full? — with Ines and Kwame.","more":"The trick inside: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","art":"art/s-train.webp","cta":"Read the story","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|story|0"},"idea-base-division-case0":{"id":"idea-base-division-case0","kind":"idea","src":"stop:base-division#case0","title":"Dividing near a base: The answer","body":"Count the hundreds (or tens, or thousands). If the spares plus the end stay under the divisor, that count is the answer.","more":"The method: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn|0"},"idea-base-division-case1":{"id":"idea-base-division-case1","kind":"idea","src":"stop:base-division#case1","title":"Dividing near a base: The remainder","body":"The spares, plus the digits on the end, are the remainder.","more":"The method: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn|1"},"idea-base-division-case2":{"id":"idea-base-division-case2","kind":"idea","src":"stop:base-division#case2","title":"Dividing near a base: One more fits (answer)","body":"The spares plus the end make more than the divisor: one more fits, so the answer goes up by one.","more":"The method: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn|2"},"idea-base-division-case3":{"id":"idea-base-division-case3","kind":"idea","src":"stop:base-division#case3","title":"Dividing near a base: One more fits (remainder)","body":"Too much left over: take one more divisor out of it to leave the true remainder.","more":"The method: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn|3"},"why-base-division-why1":{"id":"why-base-division-why1","kind":"why","src":"stop:base-division#why1","title":"Why “Dividing near a base” works","body":"Add the spare to the 91 on the end: 137. If that is less than 98, you are done. It is not — 137 holds one more 98, with 39 left. So the answer is 24, remainder 39. The book sets this out in columns (the divisor's \"complement\", 2, written under it); the columns are this same sum.","more":"The trick: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"See why","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn"},"algebra-base-division-alg":{"id":"algebra-base-division-alg","kind":"algebra","src":"stop:base-division#alg","title":"The algebra behind “Dividing near a base”","body":"N = a·B + b = a·(B − c) + (a·c + b),  so  N ÷ (B − c) = a, remainder a·c + b (if that is less than B − c)","more":"In words: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"See why","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|learn"},"moment-base-division-beat3":{"id":"moment-base-division-beat3","kind":"moment","src":"story:base-division#beat3","badge":{"id":"story","label":"A story"},"title":"Carriages of ninety-eight — on the notepad","body":"Ines: Plus the 91 on the end of 2391 — that is 137 people still standing. 46 + 91 = 137","more":"The trick in the story: Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end.","cta":"Read the story","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/base-division|story|3"},"try-base-division-L5":{"id":"try-base-division-L5","kind":"try","level":5,"src":"try:base-division@5/1#0","title":"Dividing near a base — your turn","where":"The Sutra Ladder · Level 5","route":"#/stop/base-division|drill","cta":"Practise this stop","play":{"q":"13 ÷ 7: the remainder?","opts":["6","3","7"],"after":"Each 100 holds one 98 with 2 to spare. Count the hundreds, collect the spares, and add on the end."}},"trick-ekadhika-decimals-idea":{"id":"trick-ekadhika-decimals-idea","kind":"trick","src":"stop:ekadhika-decimals#idea","title":"Recurring decimals by one more","body":"For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote. 1 ÷ 29: one more than 2 is 3. Start with 1: 1 ÷ 3 = 0, remainder 1. Put the remainder in front of the 0: 10 ÷ 3 = 3, remainder 1. In front of the 3: 13 ÷ 3 = 4, remainder 1. Then 14 ÷ 3 = 4, remainder 2. So 1 ÷ 29 = 0.0344…","more":"In algebra: 1/(10m − 1) = x  ⇒  x = (1 + x) / (10m)","cta":"Learn the trick","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn"},"story-ekadhika-decimals-open":{"id":"story-ekadhika-decimals-open","kind":"story","src":"story:ekadhika-decimals#open","badge":{"id":"story","label":"A story"},"title":"The digits of one nineteenth","body":"Under the stars, Rafi wants the digits of 1 ÷ 19. Theo’s calculator screen is too short to show them all. — with Rafi and Theo.","more":"The trick inside: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","art":"art/s-night.webp","cta":"Read the story","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|story|0"},"hook-ekadhika-decimals-hook":{"id":"hook-ekadhika-decimals-hook","kind":"hook","src":"stop:ekadhika-decimals#hook","title":"Can you? — Recurring decimals by one more","body":"1 ÷ 29 — its digits, one after another, dividing only by 3.","more":"The way in: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"Find out how","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn"},"idea-ekadhika-decimals-case0":{"id":"idea-ekadhika-decimals-case0","kind":"idea","src":"stop:ekadhika-decimals#case0","title":"Recurring decimals by one more: From the start: divide","body":"Divide by the Ekādhika; each remainder goes in front of the digit just found.","more":"The method: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn|0"},"worked-ekadhika-decimals-worked0":{"id":"worked-ekadhika-decimals-worked0","kind":"worked","src":"stop:ekadhika-decimals#worked0","title":"Worked out — Recurring decimals by one more: From the start: divide","body":"1 ÷ 29: which is the 4th digit after the point?: One more than 2 is 3. Digit 1: 1 ÷ 3 → 0 · Digit 2: remainder in front of the last digit, 10 ÷ 3 → 3 · Digit 3: remainder in front of the last digit, 13 ÷ 3 → 4 · Digit 4: remainder in front of the last digit, 14 ÷ 3 → 4","more":"What is special here: Divide by the Ekādhika; each remainder goes in front of the digit just found.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn|0"},"idea-ekadhika-decimals-case1":{"id":"idea-ekadhika-decimals-case1","kind":"idea","src":"stop:ekadhika-decimals#case1","title":"Recurring decimals by one more: From the end: multiply","body":"The repeating block ends in 1. Work leftwards: each digit is the Ekādhika × the digit on its right, plus the carry.","more":"The method: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn|1"},"worked-ekadhika-decimals-worked1":{"id":"worked-ekadhika-decimals-worked1","kind":"worked","src":"stop:ekadhika-decimals#worked1","title":"Worked out — Recurring decimals by one more: From the end: multiply","body":"1 ÷ 19: its repeating block is 18 digits long and ends in 1. Which is the 4th digit from the end of the block?: 2nd from the end: 2 × 1 = 2, keep the last digit → 2 · 3rd from the end: 2 × 2 = 4, keep the last digit → 4 · 4th from the end: 2 × 4 = 8, keep the last digit → 8","more":"What is special here: The repeating block ends in 1. Work leftwards: each digit is the Ekādhika × the digit on its right, plus the carry.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn|1"},"idea-ekadhika-decimals-case2":{"id":"idea-ekadhika-decimals-case2","kind":"idea","src":"stop:ekadhika-decimals#case2","title":"Recurring decimals by one more: The second half","body":"In the second half of the block, each digit is 9 minus the digit half a block earlier.","more":"The method: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"See it worked","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn|2"},"worked-ekadhika-decimals-worked2":{"id":"worked-ekadhika-decimals-worked2","kind":"worked","src":"stop:ekadhika-decimals#worked2","title":"Worked out — Recurring decimals by one more: The second half","body":"1 ÷ 19: its digits repeat every 18. Which is digit number 12 after the point?: One more than 1 is 2. Digit 1: 1 ÷ 2 → 0 · Digit 2: remainder in front of the last digit, 10 ÷ 2 → 5 · Digit 3: remainder in front of the last digit, 5 ÷ 2 → 2 · Half a block later, take it from 9: 9 − 2 → 7","more":"What is special here: In the second half of the block, each digit is 9 minus the digit half a block earlier.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn|2"},"why-ekadhika-decimals-why1":{"id":"why-ekadhika-decimals-why1","kind":"why","src":"stop:ekadhika-decimals#why1","title":"Why “Recurring decimals by one more” works","body":"Why: call the answer x. 29 × x = 1, so 30 × x = 1 + x — x is (1 + x) ÷ 30. Dividing by 30 is dividing by 3 and moving one place right, and the \"+ x\" is why each digit you find is fed back in as the next one to divide. The digits run the other way too: the repeating block ends in 1, and each digit to its left is 3 × the digit on its right, plus the carry.","more":"The trick: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"See why","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn"},"why-ekadhika-decimals-why2":{"id":"why-ekadhika-decimals-why2","kind":"why","src":"stop:ekadhika-decimals#why2","title":"Why “Recurring decimals by one more” works","body":"For 19, 29 and 59 the block is as long as it can be — 18, 28 and 58 digits — and its second half is the first half taken from 9: digit 10 of 1 ÷ 19 is 9 − digit 1, and so on. That is because ten to the power of half the block leaves −1 when you divide by 19 (or 29, or 59).","more":"The trick: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"See why","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn"},"algebra-ekadhika-decimals-alg":{"id":"algebra-ekadhika-decimals-alg","kind":"algebra","src":"stop:ekadhika-decimals#alg","title":"The algebra behind “Recurring decimals by one more”","body":"1/(10m − 1) = x  ⇒  x = (1 + x) / (10m)","more":"In words: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"See why","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn"},"sutra-ekadhika-decimals-sutra":{"id":"sutra-ekadhika-decimals-sutra","kind":"sutra","src":"stop:ekadhika-decimals#sutra","title":"Ekādhikena Pūrvena","body":"“by one more than the one before” — the sutra behind Recurring decimals by one more.","more":"What it does: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"Open the stop","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|learn"},"moment-ekadhika-decimals-beat3":{"id":"moment-ekadhika-decimals-beat3","kind":"moment","src":"story:ekadhika-decimals#beat3","badge":{"id":"story","label":"A story"},"title":"The digits of one nineteenth — on the notepad","body":"Theo: Remainder 0 in front of the 5 is just 5. 5 ÷ 2 is 2, remainder 1. (5 − 1) ÷ 2 = 2","more":"The trick in the story: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"Read the story","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|story|3"},"moral-ekadhika-decimals-beat5":{"id":"moral-ekadhika-decimals-beat5","kind":"moral","src":"story:ekadhika-decimals#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The digits of one nineteenth”","body":"Remainder 1 in front of the 2 is 12, and 12 ÷ 2 is 6. The fourth digit is 6.","more":"The trick in the story: For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote.","cta":"Read the story","where":"The Sutra Ladder · Level 5","level":5,"route":"#/stop/ekadhika-decimals|story|5"},"try-ekadhika-decimals-L5":{"id":"try-ekadhika-decimals-L5","kind":"try","level":5,"src":"try:ekadhika-decimals@5/1#0","title":"Recurring decimals by one more — your turn","where":"The Sutra Ladder · Level 5","route":"#/stop/ekadhika-decimals|drill","cta":"Practise this stop","play":{"q":"1 ÷ 19: its repeating block is 18 digits long and ends in 1. Which is the 3rd digit from the end of the block?","opts":["4","2","5"],"after":"For 1 ÷ 29, \"one more than the one before\" the 9 is 3. Divide by 3, and each remainder goes in front of the digit you just wrote."}},"trick-mean-fair-share-idea":{"id":"trick-mean-fair-share-idea","kind":"trick","src":"stop:mean-fair-share#idea","title":"The mean: fair shares","body":"Add everything up, then share it out equally: divide by how many numbers there are. Imagine every friend tips their tickets into one pile. Nothing is lost — the pile holds all 24. Now deal the pile out again, one each, round and round, until it is gone. Everyone ends up with the same: 6. That fair share is the mean.","more":"In algebra: mean = (x₁ + x₂ + … + xₙ) ÷ n","cta":"Learn the trick","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/mean-fair-share|learn"},"story-mean-fair-share-open":{"id":"story-mean-fair-share-open","kind":"story","src":"story:mean-fair-share#open","badge":{"id":"story","label":"A story"},"title":"Sharing the tickets","body":"Four friends play the games. Nova wins 3 tickets, Rafi 7, Pip 5 and Suki 9. They agree to share them fairly. — with Nova and Rafi.","more":"The trick inside: Add everything up, then share it out equally: divide by how many numbers there are.","art":"art/s-carnival.webp","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/mean-fair-share|story|0"},"worked-mean-fair-share-worked0":{"id":"worked-mean-fair-share-worked0","kind":"worked","src":"stop:mean-fair-share#worked0","title":"Worked out — The mean: fair shares","body":"The mean of 3, 7, 5, 9: Add them all up → 24 · How many numbers? → 4 · 24 ÷ 4 → 6","more":"The method: Add everything up, then share it out equally: divide by how many numbers there are.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/mean-fair-share|learn|0"},"why-mean-fair-share-why2":{"id":"why-mean-fair-share-why2","kind":"why","src":"stop:mean-fair-share#why2","title":"Why “The mean: fair shares” works","body":"That is why the mean needs both steps. Adding makes the pile; dividing by how many people deals it out. Divide by the wrong number and somebody gets cheated.","more":"The trick: Add everything up, then share it out equally: divide by how many numbers there are.","cta":"See why","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/mean-fair-share|learn"},"moment-mean-fair-share-beat2":{"id":"moment-mean-fair-share-beat2","kind":"moment","src":"story:mean-fair-share#beat2","badge":{"id":"story","label":"A story"},"title":"Sharing the tickets — on the notepad","body":"Nova: Now deal them out, one each, round and round, between the four of us. 24 ÷ 4 = 6","more":"The trick in the story: Add everything up, then share it out equally: divide by how many numbers there are.","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/mean-fair-share|story|2"},"try-mean-fair-share-L5":{"id":"try-mean-fair-share-L5","kind":"try","level":5,"src":"try:mean-fair-share@5/1#0","title":"The mean: fair shares — your turn","where":"The Data Carnival · Level 5","route":"#/stop/mean-fair-share|drill","cta":"Practise this stop","play":{"q":"The mean of 6, 10, 2 = ?","opts":["6","18","3"],"after":"Add everything up, then share it out equally: divide by how many numbers there are."}},"trick-data-range-idea":{"id":"trick-data-range-idea","kind":"trick","src":"stop:data-range#idea","title":"The range: how spread out?","body":"Find the largest and the smallest, and take one from the other. Two teams can have the same mean and still be very different: one where everyone scores about 20, and one where some score 2 and some score 40. The range tells them apart.","more":"In algebra: range = largest − smallest","cta":"Learn the trick","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/data-range|learn"},"story-data-range-open":{"id":"story-data-range-open","kind":"story","src":"story:data-range#open","badge":{"id":"story","label":"A story"},"title":"Two cricket teams","body":"The Reds scored 14, 31, 25, 9 and 27 runs. Pip wants to know how spread out the scores are. — with Kwame and Pip.","more":"The trick inside: Find the largest and the smallest, and take one from the other.","art":"art/s-cricket.webp","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/data-range|story|0"},"worked-data-range-worked0":{"id":"worked-data-range-worked0","kind":"worked","src":"stop:data-range#worked0","title":"Worked out — The range: how spread out?","body":"The range of 14, 31, 25, 9, 27: The largest → 31 · The smallest → 9 · 31 − 9 → 22","more":"The method: Find the largest and the smallest, and take one from the other.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/data-range|learn|0"},"why-data-range-why2":{"id":"why-data-range-why2","kind":"why","src":"stop:data-range#why2","title":"Why “The range: how spread out?” works","body":"Only the two ends matter. Every other number sits somewhere in between, so it cannot make the spread any wider.","more":"The trick: Find the largest and the smallest, and take one from the other.","cta":"See why","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/data-range|learn"},"moment-data-range-beat3":{"id":"moment-data-range-beat3","kind":"moment","src":"story:data-range#beat3","badge":{"id":"story","label":"A story"},"title":"Two cricket teams — on the notepad","body":"Kwame: The range is the distance between them. 31 − 9 = 22","more":"The trick in the story: Find the largest and the smallest, and take one from the other.","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/data-range|story|3"},"try-data-range-L5":{"id":"try-data-range-L5","kind":"try","level":5,"src":"try:data-range@5/1#0","title":"The range: how spread out? — your turn","where":"The Data Carnival · Level 5","route":"#/stop/data-range|drill","cta":"Practise this stop","play":{"q":"The range of 4, 10, 5, 5 = ?","opts":["6","10","4"],"after":"Find the largest and the smallest, and take one from the other."}},"trick-think-of-a-number-idea":{"id":"trick-think-of-a-number-idea","kind":"trick","src":"stop:think-of-a-number#idea","title":"Working backwards","body":"Start at the end and undo each step, last one first: undo + with −, and × with ÷. Think of the number going through a machine: first × 3, then + 4, and out comes 19. To get back, walk the path the other way — the last thing done is the first thing undone.","more":"In algebra: ((x × a) + b = c) ⇒ x = (c − b) ÷ a","cta":"Learn the trick","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/think-of-a-number|learn"},"story-think-of-a-number-open":{"id":"story-think-of-a-number-open","kind":"story","src":"story:think-of-a-number#open","badge":{"id":"story","label":"A story"},"title":"The mind-reader","body":"A sign on the tent says \"The Mind-Reader\". Pip thinks of a number, times it by 3, adds 4, and says: \"19\". — with Vesper and Pip.","more":"The trick inside: Start at the end and undo each step, last one first: undo + with −, and × with ÷.","art":"art/s-carnival.webp","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/think-of-a-number|story|0"},"worked-think-of-a-number-worked0":{"id":"worked-think-of-a-number-worked0","kind":"worked","src":"stop:think-of-a-number#worked0","title":"Worked out — Working backwards","body":"? → × 3 → + 4 → 19. What number went in?: Undo + 4: 19 − 4 → 15 · Undo × 3: 15 ÷ 3 → 5","more":"The method: Start at the end and undo each step, last one first: undo + with −, and × with ÷.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/think-of-a-number|learn|0"},"why-think-of-a-number-why2":{"id":"why-think-of-a-number-why2","kind":"why","src":"stop:think-of-a-number#why2","title":"Why “Working backwards” works","body":"It is like taking off your shoes before your socks: you put the socks on first, so they come off last. Check by running 5 forwards: 5 × 3 = 15, 15 + 4 = 19.","more":"The trick: Start at the end and undo each step, last one first: undo + with −, and × with ÷.","cta":"See why","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/think-of-a-number|learn"},"moment-think-of-a-number-beat3":{"id":"moment-think-of-a-number-beat3","kind":"moment","src":"story:think-of-a-number#beat3","badge":{"id":"story","label":"A story"},"title":"The mind-reader — on the notepad","body":"Vesper: Before that you timesed by 3. Undo that too. 15 ÷ 3 = 5","more":"The trick in the story: Start at the end and undo each step, last one first: undo + with −, and × with ÷.","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/think-of-a-number|story|3"},"try-think-of-a-number-L5":{"id":"try-think-of-a-number-L5","kind":"try","level":5,"src":"try:think-of-a-number@5/1#0","title":"Working backwards — your turn","where":"The Data Carnival · Level 5","route":"#/stop/think-of-a-number|drill","cta":"Practise this stop","play":{"q":"? → × 3 → + 7 → 28. What number went in?","opts":["7","21","8"],"after":"Start at the end and undo each step, last one first: undo + with −, and × with ÷."}},"trick-multi-step-problems-idea":{"id":"trick-multi-step-problems-idea","kind":"trick","src":"stop:multi-step-problems#idea","title":"Problems in steps","body":"Find the question inside the question: work out the part you need first, then use it. A long problem is a few short ones in a row. \"How many tokens are left?\" cannot be answered until you know how many were spent — so that is the first question, and its answer feeds the second.","more":"In algebra: left = start − (number × price)","cta":"Learn the trick","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn"},"story-multi-step-problems-open":{"id":"story-multi-step-problems-open","kind":"story","src":"story:multi-step-problems#open","badge":{"id":"story","label":"A story"},"title":"Tokens at the fair","body":"Rafi has 50 tokens. He goes on 3 rides that cost 8 tokens each. — with Ines and Rafi.","more":"The trick inside: Find the question inside the question: work out the part you need first, then use it.","art":"art/s-market.webp","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|story|0"},"hook-multi-step-problems-hook":{"id":"hook-multi-step-problems-hook","kind":"hook","src":"stop:multi-step-problems#hook","title":"Can you? — Problems in steps","body":"50 tokens, 3 rides at 8 tokens each. What is left? Two sums hiding in one question.","more":"The way in: Find the question inside the question: work out the part you need first, then use it.","cta":"Find out how","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn"},"idea-multi-step-problems-case0":{"id":"idea-multi-step-problems-case0","kind":"idea","src":"stop:multi-step-problems#case0","title":"Problems in steps: What is left?","body":"You cannot take away until you know what was spent — so the times sum comes first.","more":"The method: Find the question inside the question: work out the part you need first, then use it.","cta":"See it worked","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|0"},"worked-multi-step-problems-worked0":{"id":"worked-multi-step-problems-worked0","kind":"worked","src":"stop:multi-step-problems#worked0","title":"Worked out — Problems in steps: What is left?","body":"You have 50 tokens. You go on 3 rides at 8 tokens each. How many tokens are left?: Spent on rides: 3 × 8 → 24 · 50 − 24 → 26","more":"What is special here: You cannot take away until you know what was spent — so the times sum comes first.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|0"},"idea-multi-step-problems-case1":{"id":"idea-multi-step-problems-case1","kind":"idea","src":"stop:multi-step-problems#case1","title":"Problems in steps: Two things bought","body":"Two different prices make two little times sums. Work each one out, then add them.","more":"The method: Find the question inside the question: work out the part you need first, then use it.","cta":"See it worked","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|1"},"worked-multi-step-problems-worked1":{"id":"worked-multi-step-problems-worked1","kind":"worked","src":"stop:multi-step-problems#worked1","title":"Worked out — Problems in steps: Two things bought","body":"Popcorn costs 5 tokens and a drink costs 4. You buy 3 popcorn and 2 drinks. How many tokens altogether?: 3 × 5 → 15 · 2 × 4 → 8 · 15 + 8 → 23","more":"What is special here: Two different prices make two little times sums. Work each one out, then add them.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|1"},"idea-multi-step-problems-case2":{"id":"idea-multi-step-problems-case2","kind":"idea","src":"stop:multi-step-problems#case2","title":"Problems in steps: Change from a payment","body":"Cost the candy floss, cost the lollies, add them — and only then take the total from what you paid.","more":"The method: Find the question inside the question: work out the part you need first, then use it.","cta":"See it worked","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|2"},"worked-multi-step-problems-worked2":{"id":"worked-multi-step-problems-worked2","kind":"worked","src":"stop:multi-step-problems#worked2","title":"Worked out — Problems in steps: Change from a payment","body":"Candy floss costs 8 tokens and a lolly costs 5. You buy 2 candy floss and 3 lollies, and pay with 50 tokens. What is your change?: 2 × 8 → 16 · 3 × 5 → 15 · Total: 16 + 15 → 31 · 50 − 31 → 19","more":"What is special here: Cost the candy floss, cost the lollies, add them — and only then take the total from what you paid.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|2"},"idea-multi-step-problems-case3":{"id":"idea-multi-step-problems-case3","kind":"idea","src":"stop:multi-step-problems#case3","title":"Problems in steps: Breaks between shows","body":"There is a break between each pair of shows, not after the last — so one fewer break than shows.","more":"The method: Find the question inside the question: work out the part you need first, then use it.","cta":"See it worked","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|3"},"worked-multi-step-problems-worked3":{"id":"worked-multi-step-problems-worked3","kind":"worked","src":"stop:multi-step-problems#worked3","title":"Worked out — Problems in steps: Breaks between shows","body":"There are 3 puppet shows in a row. Each lasts 20 minutes, with a 10-minute break between shows. How many minutes from the start of the first to the end of the last?: Show time: 3 × 20 → 60 · Breaks: there are 2, so 2 × 10 → 20 · 60 + 20 → 80","more":"What is special here: There is a break between each pair of shows, not after the last — so one fewer break than shows.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|3"},"idea-multi-step-problems-case4":{"id":"idea-multi-step-problems-case4","kind":"idea","src":"stop:multi-step-problems#case4","title":"Problems in steps: Turns in a queue","body":"First find how many rides it takes to fit everyone in, then times by how long each ride lasts.","more":"The method: Find the question inside the question: work out the part you need first, then use it.","cta":"See it worked","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|4"},"worked-multi-step-problems-worked4":{"id":"worked-multi-step-problems-worked4","kind":"worked","src":"stop:multi-step-problems#worked4","title":"Worked out — Problems in steps: Turns in a queue","body":"12 children are queuing for the dodgems. 4 can ride at once, and each ride lasts 5 minutes. How many minutes until everyone has had a go?: How many rides? 12 ÷ 4 → 3 · 3 × 5 → 15","more":"What is special here: First find how many rides it takes to fit everyone in, then times by how long each ride lasts.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|4"},"idea-multi-step-problems-case5":{"id":"idea-multi-step-problems-case5","kind":"idea","src":"stop:multi-step-problems#case5","title":"Problems in steps: Pool, then share","body":"Put all the sweets in one pile first, then share the pile equally.","more":"The method: Find the question inside the question: work out the part you need first, then use it.","cta":"See it worked","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|5"},"worked-multi-step-problems-worked5":{"id":"worked-multi-step-problems-worked5","kind":"worked","src":"stop:multi-step-problems#worked5","title":"Worked out — Problems in steps: Pool, then share","body":"4 friends buy 3 packs of sweets with 8 in each pack. They share them equally. How many does each friend get?: All the sweets: 3 × 8 → 24 · 24 ÷ 4 → 6","more":"What is special here: Put all the sweets in one pile first, then share the pile equally.","cta":"Watch it step by step","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn|5"},"why-multi-step-problems-why1":{"id":"why-multi-step-problems-why1","kind":"why","src":"stop:multi-step-problems#why1","title":"Why “Problems in steps” works","body":"Write each step as its own little sum. 3 rides at 8 tokens is 3 × 8 = 24 spent; 50 − 24 = 26 left. Each sum is easy; the skill is putting them in the right order. Watch the gaps, too: 3 shows in a row have only 2 breaks between them, like 3 fence posts with 2 gaps.","more":"The trick: Find the question inside the question: work out the part you need first, then use it.","cta":"See why","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn"},"why-multi-step-problems-why2":{"id":"why-multi-step-problems-why2","kind":"why","src":"stop:multi-step-problems#why2","title":"Why “Problems in steps” works","body":"Then check the answer makes sense: you cannot have more tokens left than you started with, and a show cannot finish before it starts. A silly answer means a step was done the wrong way round.","more":"The trick: Find the question inside the question: work out the part you need first, then use it.","cta":"See why","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn"},"algebra-multi-step-problems-alg":{"id":"algebra-multi-step-problems-alg","kind":"algebra","src":"stop:multi-step-problems#alg","title":"The algebra behind “Problems in steps”","body":"left = start − (number × price)","more":"In words: Find the question inside the question: work out the part you need first, then use it.","cta":"See why","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|learn"},"moment-multi-step-problems-beat3":{"id":"moment-multi-step-problems-beat3","kind":"moment","src":"story:multi-step-problems#beat3","badge":{"id":"story","label":"A story"},"title":"Tokens at the fair — on the notepad","body":"Rafi: Now take that from what I started with. 50 − 24 = 26","more":"The trick in the story: Find the question inside the question: work out the part you need first, then use it.","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|story|3"},"moral-multi-step-problems-beat5":{"id":"moral-multi-step-problems-beat5","kind":"moral","src":"story:multi-step-problems#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Tokens at the fair”","body":"Twenty-six tokens left. Two little sums, in the right order.","more":"The trick in the story: Find the question inside the question: work out the part you need first, then use it.","cta":"Read the story","where":"The Data Carnival · Level 5","level":5,"route":"#/stop/multi-step-problems|story|5"},"try-multi-step-problems-L5":{"id":"try-multi-step-problems-L5","kind":"try","level":5,"src":"try:multi-step-problems@5/1#0","title":"Problems in steps — your turn","where":"The Data Carnival · Level 5","route":"#/stop/multi-step-problems|drill","cta":"Practise this stop","play":{"q":"2 friends buy 2 packs of sweets with 8 in each pack. They share them equally. How many does each friend get?","opts":["8","16","9"],"after":"Find the question inside the question: work out the part you need first, then use it."}},"trick-count-triangles-idea":{"id":"trick-count-triangles-idea","kind":"trick","src":"stop:count-triangles#idea","title":"Counting triangles","body":"Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule. Your eye finds the small triangles and misses the big ones made of several pieces. So stop looking and start sorting. In a fan, every triangle has the top corner as one of its points, and its two slanting sides are two of the lines that leave the top. Choose any two of those lines and the bottom edge closes them into exactly one triangle. So the count is just \"how many ways to choose two lines\".","more":"In algebra: fan with p lines from the top and m cross-lines: p(p − 1)/2 × (m + 1)","cta":"Learn the trick","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn"},"story-count-triangles-open":{"id":"story-count-triangles-open","kind":"story","src":"story:count-triangles#open","badge":{"id":"story","label":"A story"},"title":"The bunting puzzle","body":"At the fair, a big wooden triangle hangs over the gate. Strings run from its top corner to 5 points along the bottom bar. — with Pip and Rafi.","more":"The trick inside: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","art":"art/s-fair.webp","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|story|0"},"hook-count-triangles-hook":{"id":"hook-count-triangles-hook","kind":"hook","src":"stop:count-triangles#hook","title":"Can you? — Counting triangles","body":"Lines fan out from the top corner of a triangle. How many triangles can you see — all of them?","more":"The way in: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"Find out how","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn"},"idea-count-triangles-case0":{"id":"idea-count-triangles-case0","kind":"idea","src":"stop:count-triangles#case0","title":"Counting triangles: A fan from one corner","body":"Every triangle uses the top corner and two of the lines leaving it, so count the pairs of lines: 5 × 4 ÷ 2.","more":"The method: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn|0"},"worked-count-triangles-worked0":{"id":"worked-count-triangles-worked0","kind":"worked","src":"stop:count-triangles#worked0","title":"Worked out — Counting triangles: A fan from one corner","body":"Lines run from the top corner to 5 points on the bottom edge (the two ends count). How many triangles are there altogether?: Lines leaving the top corner → 5 · Ways to choose two of them: 5 × 4 ÷ 2 → 10","more":"What is special here: Every triangle uses the top corner and two of the lines leaving it, so count the pairs of lines: 5 × 4 ÷ 2.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn|0"},"idea-count-triangles-case1":{"id":"idea-count-triangles-case1","kind":"idea","src":"stop:count-triangles#case1","title":"Counting triangles: A fan with a cross-line","body":"Each pair of slanting lines now makes a triangle with the bottom AND with the line across — so multiply the pairs by the number of across lines.","more":"The method: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn|1"},"worked-count-triangles-worked1":{"id":"worked-count-triangles-worked1","kind":"worked","src":"stop:count-triangles#worked1","title":"Worked out — Counting triangles: A fan with a cross-line","body":"Lines run from the top corner to 4 points on the bottom edge (the two ends count), and 1 line crosses straight over the whole triangle. How many triangles are there?: Lines leaving the top corner → 4 · Ways to choose two of them: 4 × 3 ÷ 2 → 6 · Lines going across that can close a triangle (the bottom edge counts) → 2 · Triangles: pairs × across lines → 12","more":"What is special here: Each pair of slanting lines now makes a triangle with the bottom AND with the line across — so multiply the pairs by the number of across lines.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn|1"},"idea-count-triangles-case2":{"id":"idea-count-triangles-case2","kind":"idea","src":"stop:count-triangles#case2","title":"Counting triangles: A grid of triangles","body":"Sort by size and by direction. Count up-pointing triangles of each size, then the down-pointing ones — the ones most people miss.","more":"The method: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn|2"},"worked-count-triangles-worked2":{"id":"worked-count-triangles-worked2","kind":"worked","src":"stop:count-triangles#worked2","title":"Worked out — Counting triangles: A grid of triangles","body":"Each side of the big triangle is cut into 3 equal parts, and the lines make a grid of small triangles. How many triangles of any size are there?: Triangles pointing UP, of every size → 10 · Triangles pointing DOWN, of every size → 3 · All the triangles → 13","more":"What is special here: Sort by size and by direction. Count up-pointing triangles of each size, then the down-pointing ones — the ones most people miss.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn|2"},"why-count-triangles-why1":{"id":"why-count-triangles-why1","kind":"why","src":"stop:count-triangles#why1","title":"Why “Counting triangles” works","body":"With 5 lines leaving the top, the first line can pair with 4 others, the second with 3 new ones, then 2, then 1: 4 + 3 + 2 + 1 = 10. That is the same as 5 × 4 ÷ 2 — every pair is counted twice when each line names its partners, so halve it. Add a line straight across the fan and every pair of slanting lines makes a second triangle with it, so the count doubles.","more":"The trick: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn"},"why-count-triangles-why2":{"id":"why-count-triangles-why2","kind":"why","src":"stop:count-triangles#why2","title":"Why “Counting triangles” works","body":"A triangle cut into a grid of small triangles is sorted a different way: by size, and by which way it points. Count the ones pointing up for each size, then the ones pointing down — the upside-down ones are the ones people forget, and the reason the answer is bigger than you think.","more":"The trick: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn"},"algebra-count-triangles-alg":{"id":"algebra-count-triangles-alg","kind":"algebra","src":"stop:count-triangles#alg","title":"The algebra behind “Counting triangles”","body":"fan with p lines from the top and m cross-lines: p(p − 1)/2 × (m + 1)","more":"In words: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|learn"},"moment-count-triangles-beat4":{"id":"moment-count-triangles-beat4","kind":"moment","src":"story:count-triangles#beat4","badge":{"id":"story","label":"A story"},"title":"The bunting puzzle — on the notepad","body":"Rafi: Or count from every string and halve, because each pair got counted from both ends. 5 × 4 ÷ 2 = 10","more":"The trick in the story: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|story|4"},"moral-count-triangles-beat5":{"id":"moral-count-triangles-beat5","kind":"moral","src":"story:count-triangles#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The bunting puzzle”","body":"Ten triangles over the gate — and I only saw four.","more":"The trick in the story: Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-triangles|story|5"},"try-count-triangles-L5":{"id":"try-count-triangles-L5","kind":"try","level":5,"src":"try:count-triangles@5/1#0","title":"Counting triangles — your turn","where":"The Figure Fair · Level 5","route":"#/stop/count-triangles|drill","cta":"Practise this stop","play":{"q":"Lines run from the top corner to 3 points on the bottom edge (the two ends count). How many triangles are there altogether?","opts":["3","4","2"],"after":"Do not hunt for triangles one by one: sort them by what they are made of, then count each sort with a rule."}},"trick-count-rectangles-idea":{"id":"trick-count-rectangles-idea","kind":"trick","src":"stop:count-rectangles#idea","title":"Counting rectangles","body":"A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply. Look at the lines, not the squares. Every rectangle in the grid has a left side and a right side, and both lie on two of the upright lines. It has a top and a bottom on two of the across lines. Pick any two upright lines and any two across lines and you have drawn exactly one rectangle — and every rectangle comes from exactly one such choice.","more":"In algebra: rectangles in a w × h grid = C(w + 1, 2) × C(h + 1, 2)","cta":"Learn the trick","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn"},"story-count-rectangles-open":{"id":"story-count-rectangles-open","kind":"story","src":"story:count-rectangles#open","badge":{"id":"story","label":"A story"},"title":"The chocolate bar","body":"Mira breaks open a chocolate bar 4 pieces wide and 3 pieces tall. Nova bets her there are only twelve rectangles in it. — with Nova and Mira.","more":"The trick inside: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","art":"art/s-kitchen.webp","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|story|0"},"hook-count-rectangles-hook":{"id":"hook-count-rectangles-hook","kind":"hook","src":"stop:count-rectangles#hook","title":"Can you? — Counting rectangles","body":"A chocolate bar is 4 pieces wide and 3 pieces tall. How many rectangles are hiding in it?","more":"The way in: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"Find out how","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn"},"idea-count-rectangles-case0":{"id":"idea-count-rectangles-case0","kind":"idea","src":"stop:count-rectangles#case0","title":"Counting rectangles: One row of squares","body":"In a strip, a rectangle is just a choice of two of the dividing lines for its two ends: 6 lines give 6 × 5 ÷ 2 = 15.","more":"The method: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn|0"},"worked-count-rectangles-worked0":{"id":"worked-count-rectangles-worked0","kind":"worked","src":"stop:count-rectangles#worked0","title":"Worked out — Counting rectangles: One row of squares","body":"A strip of 5 squares in a row. How many rectangles can you find? (A square counts as a rectangle.): Dividing lines across the strip (both ends count) → 6 · Choose two of them for the ends: 6 × 5 ÷ 2 → 15","more":"What is special here: In a strip, a rectangle is just a choice of two of the dividing lines for its two ends: 6 lines give 6 × 5 ÷ 2 = 15.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn|0"},"idea-count-rectangles-case1":{"id":"idea-count-rectangles-case1","kind":"idea","src":"stop:count-rectangles#case1","title":"Counting rectangles: A grid of rectangles","body":"Choose two upright lines and two across lines. Every left-right choice goes with every top-bottom choice, so multiply.","more":"The method: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn|1"},"worked-count-rectangles-worked1":{"id":"worked-count-rectangles-worked1","kind":"worked","src":"stop:count-rectangles#worked1","title":"Worked out — Counting rectangles: A grid of rectangles","body":"A grid 4 squares wide and 3 squares tall. How many rectangles of any size can you find? (Squares count too.): Choose 2 of the 5 upright lines: 5 × 4 ÷ 2 → 10 · Choose 2 of the 4 across lines: 4 × 3 ÷ 2 → 6 · Multiply: every pair of sides goes with every top and bottom → 60","more":"What is special here: Choose two upright lines and two across lines. Every left-right choice goes with every top-bottom choice, so multiply.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn|1"},"idea-count-rectangles-case2":{"id":"idea-count-rectangles-case2","kind":"idea","src":"stop:count-rectangles#case2","title":"Counting rectangles: Only the squares","body":"Squares need equal sides, so count them size by size: each size up fits one fewer way across and one fewer way down.","more":"The method: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn|2"},"worked-count-rectangles-worked2":{"id":"worked-count-rectangles-worked2","kind":"worked","src":"stop:count-rectangles#worked2","title":"Worked out — Counting rectangles: Only the squares","body":"A grid 4 squares wide and 3 squares tall. How many squares of any size can you find?: 1 by 1 squares: 4 × 3 → 12 · 2 by 2 squares: 3 × 2 → 6 · 3 by 3 squares: 2 × 1 → 2 · All the squares → 20","more":"What is special here: Squares need equal sides, so count them size by size: each size up fits one fewer way across and one fewer way down.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn|2"},"why-count-rectangles-why1":{"id":"why-count-rectangles-why1","kind":"why","src":"stop:count-rectangles#why1","title":"Why “Counting rectangles” works","body":"A grid 4 squares wide has 5 upright lines (one more than the squares, like fence posts). Two of 5 can be chosen in 5 × 4 ÷ 2 = 10 ways. A grid 3 tall has 4 across lines, and two of those can be chosen in 4 × 3 ÷ 2 = 6 ways. Every left-and-right choice goes with every top-and-bottom choice, so there are 10 × 6 = 60 rectangles.","more":"The trick: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn"},"why-count-rectangles-why2":{"id":"why-count-rectangles-why2","kind":"why","src":"stop:count-rectangles#why2","title":"Why “Counting rectangles” works","body":"Squares are counted by size instead. In a 4 by 3 grid there are 4 × 3 one-by-one squares, 3 × 2 two-by-two squares and 2 × 1 three-by-three squares: each bigger size fits one fewer way across and one fewer way down.","more":"The trick: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn"},"algebra-count-rectangles-alg":{"id":"algebra-count-rectangles-alg","kind":"algebra","src":"stop:count-rectangles#alg","title":"The algebra behind “Counting rectangles”","body":"rectangles in a w × h grid = C(w + 1, 2) × C(h + 1, 2)","more":"In words: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|learn"},"moment-count-rectangles-beat4":{"id":"moment-count-rectangles-beat4","kind":"moment","src":"story:count-rectangles#beat4","badge":{"id":"story","label":"A story"},"title":"The chocolate bar — on the notepad","body":"Nova: And two of the 4 across lines for its top and bottom. 4 × 3 ÷ 2 = 6","more":"The trick in the story: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|story|4"},"moral-count-rectangles-beat6":{"id":"moral-count-rectangles-beat6","kind":"moral","src":"story:count-rectangles#beat6","badge":{"id":"story","label":"A story"},"title":"Nova, in “The chocolate bar”","body":"Sixty rectangles in one bar. I owe you a piece.","more":"The trick in the story: A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/count-rectangles|story|6"},"try-count-rectangles-L5":{"id":"try-count-rectangles-L5","kind":"try","level":5,"src":"try:count-rectangles@5/1#0","title":"Counting rectangles — your turn","where":"The Figure Fair · Level 5","route":"#/stop/count-rectangles|drill","cta":"Practise this stop","play":{"q":"A strip of 6 squares in a row. How many rectangles can you find? (A square counts as a rectangle.) = ?","opts":["21","7","22"],"after":"A rectangle is fixed by choosing its two side lines and its two top-and-bottom lines — count the choices and multiply."}},"trick-handshakes-idea":{"id":"trick-handshakes-idea","kind":"trick","src":"stop:handshakes#idea","title":"Handshakes and matches","body":"Count from every person, then halve — because every handshake has two people in it and got counted by both. Stand in the shoes of one person. With 10 friends, she shakes hands with the other 9. So does everyone else, so 10 people × 9 handshakes each = 90. But look at any one handshake: Ana shaking hands with Ben was counted once when we stood in Ana's shoes and again in Ben's. Every handshake was counted exactly twice, so the real number is 90 ÷ 2 = 45.","more":"In algebra: n people, one handshake per pair: n(n − 1) ÷ 2","cta":"Learn the trick","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn"},"story-handshakes-open":{"id":"story-handshakes-open","kind":"story","src":"story:handshakes#open","badge":{"id":"story","label":"A story"},"title":"The first day of the club","body":"Ten new members meet in the hall for the maths club, and everyone shakes hands with everyone else once. — with Dax and Suki.","more":"The trick inside: Count from every person, then halve — because every handshake has two people in it and got counted by both.","art":"art/s-hall.webp","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|story|0"},"hook-handshakes-hook":{"id":"hook-handshakes-hook","kind":"hook","src":"stop:handshakes#hook","title":"Can you? — Handshakes and matches","body":"Ten friends all shake hands with each other once. Is that 100 handshakes? 90? Fewer?","more":"The way in: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"Find out how","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn"},"idea-handshakes-case0":{"id":"idea-handshakes-case0","kind":"idea","src":"stop:handshakes#case0","title":"Handshakes and matches: Everyone shakes once","body":"Each of 6 people shakes 5 hands: 6 × 5 = 30 — but that counts every handshake from both ends, so halve it.","more":"The method: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|0"},"worked-handshakes-worked0":{"id":"worked-handshakes-worked0","kind":"worked","src":"stop:handshakes#worked0","title":"Worked out — Handshakes and matches: Everyone shakes once","body":"6 friends meet, and every two of them shake hands once. How many handshakes are there?: Hands one person shakes → 5 · Counted from every person: 6 × 5 → 30 · Each handshake was counted twice — halve → 15","more":"What is special here: Each of 6 people shakes 5 hands: 6 × 5 = 30 — but that counts every handshake from both ends, so halve it.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|0"},"idea-handshakes-case1":{"id":"idea-handshakes-case1","kind":"idea","src":"stop:handshakes#case1","title":"Handshakes and matches: Home and away","body":"When every pair plays twice, the two games really are different. Count each team's home games and do not halve.","more":"The method: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|1"},"worked-handshakes-worked1":{"id":"worked-handshakes-worked1","kind":"worked","src":"stop:handshakes#worked1","title":"Worked out — Handshakes and matches: Home and away","body":"5 teams are in a league. Every team plays every other team twice: once at home and once away. How many games are played?: Home games for one team (one against each other team) → 4 · Home games for all 5 teams — every game is someone's home game → 20","more":"What is special here: When every pair plays twice, the two games really are different. Count each team's home games and do not halve.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|1"},"idea-handshakes-case2":{"id":"idea-handshakes-case2","kind":"idea","src":"stop:handshakes#case2","title":"Handshakes and matches: Working backwards","body":"Double the handshakes, then find a number times the one just below it that makes that. The bigger number is the people.","more":"The method: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|2"},"worked-handshakes-worked2":{"id":"worked-handshakes-worked2","kind":"worked","src":"stop:handshakes#worked2","title":"Worked out — Handshakes and matches: Working backwards","body":"At a party, every two guests shook hands once — 28 handshakes in all. How many guests were there?: Double the handshakes: 28 × 2 → 56 · That is a number times the one just below it. The bigger number is → 8","more":"What is special here: Double the handshakes, then find a number times the one just below it that makes that. The bigger number is the people.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|2"},"idea-handshakes-case3":{"id":"idea-handshakes-case3","kind":"idea","src":"stop:handshakes#case3","title":"Handshakes and matches: Couples skip partners","body":"Each person shakes everyone except themselves and their own partner. Count from every person, then halve as before.","more":"The method: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|3"},"worked-handshakes-worked3":{"id":"worked-handshakes-worked3","kind":"worked","src":"stop:handshakes#worked3","title":"Worked out — Handshakes and matches: Couples skip partners","body":"4 couples meet. Everyone shakes hands once with everyone else — except their own partner. How many handshakes are there?: People altogether → 8 · Hands one person shakes (not themselves, not their partner) → 6 · Counted from every person: 8 × 6 → 48 · Halve: each handshake was counted twice → 24","more":"What is special here: Each person shakes everyone except themselves and their own partner. Count from every person, then halve as before.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn|3"},"why-handshakes-why1":{"id":"why-handshakes-why1","kind":"why","src":"stop:handshakes#why1","title":"Why “Handshakes and matches” works","body":"A league where every team plays every other team twice — once at home, once away — is different. Now Ana-at-home-to-Ben and Ben-at-home-to-Ana really are two games. Count each team's home games and you are done, with nothing to halve: 10 teams × 9 home games = 90.","more":"The trick: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn"},"why-handshakes-why2":{"id":"why-handshakes-why2","kind":"why","src":"stop:handshakes#why2","title":"Why “Handshakes and matches” works","body":"The same picture runs backwards. If 45 handshakes happened, double it to 90 and ask: which number times the number one below it makes 90? 10 × 9 — so there were 10 people. And if partners do not shake hands with each other, count everyone's handshakes leaving out themselves AND their partner, then halve.","more":"The trick: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn"},"algebra-handshakes-alg":{"id":"algebra-handshakes-alg","kind":"algebra","src":"stop:handshakes#alg","title":"The algebra behind “Handshakes and matches”","body":"n people, one handshake per pair: n(n − 1) ÷ 2","more":"In words: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|learn"},"moment-handshakes-beat4":{"id":"moment-handshakes-beat4","kind":"moment","src":"story:handshakes#beat4","badge":{"id":"story","label":"A story"},"title":"The first day of the club — on the notepad","body":"Suki: Halve it. 90 ÷ 2 = 45","more":"The trick in the story: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|story|4"},"moral-handshakes-beat5":{"id":"moral-handshakes-beat5","kind":"moral","src":"story:handshakes#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The first day of the club”","body":"Forty-five handshakes. Still a lot, but my hand will live.","more":"The trick in the story: Count from every person, then halve — because every handshake has two people in it and got counted by both.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/handshakes|story|5"},"try-handshakes-L5":{"id":"try-handshakes-L5","kind":"try","level":5,"src":"try:handshakes@5/1#0","title":"Handshakes and matches — your turn","where":"The Figure Fair · Level 5","route":"#/stop/handshakes|drill","cta":"Practise this stop","play":{"q":"4 friends meet, and every two of them shake hands once. How many handshakes are there?","opts":["6","3","12"],"after":"Count from every person, then halve — because every handshake has two people in it and got counted by both."}},"trick-staircase-perimeter-idea":{"id":"trick-staircase-perimeter-idea","kind":"trick","src":"stop:staircase-perimeter#idea","title":"Staircase perimeters","body":"Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's. Walk round the staircase. Every piece of the edge goes either across or up-and-down. Now imagine sliding each little across-piece of the steps straight up to the top: they line up end to end and fill the top edge of a rectangle exactly. Slide each little up-piece across to the side and they fill the right edge.","more":"In algebra: staircase: P = 2(W + H);  with a slot d deep: P = 2(W + H) + 2d","cta":"Learn the trick","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn"},"story-staircase-perimeter-open":{"id":"story-staircase-perimeter-open","kind":"story","src":"story:staircase-perimeter#open","badge":{"id":"story","label":"A story"},"title":"The garden steps","body":"A flower bed is cut like a staircase, 9 metres wide and 7 metres tall. Dax needs edging all the way round it. — with Mira and Dax.","more":"The trick inside: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","art":"art/s-garden.webp","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|story|0"},"hook-staircase-perimeter-hook":{"id":"hook-staircase-perimeter-hook","kind":"hook","src":"stop:staircase-perimeter#hook","title":"Can you? — Staircase perimeters","body":"A staircase shape has lots of little steps and only two lengths marked. Can you still find its perimeter?","more":"The way in: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"Find out how","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn"},"idea-staircase-perimeter-case0":{"id":"idea-staircase-perimeter-case0","kind":"idea","src":"stop:staircase-perimeter#case0","title":"Staircase perimeters: The outside is marked","body":"Only the width and the height are given — and that is all you need. The steps slide out to make the rectangle's other two sides.","more":"The method: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn|0"},"worked-staircase-perimeter-worked0":{"id":"worked-staircase-perimeter-worked0","kind":"worked","src":"stop:staircase-perimeter#worked0","title":"Worked out — Staircase perimeters: The outside is marked","body":"A staircase shape with 3 steps is 9 cm wide and 7 cm tall. What is its perimeter, in cm?: All the across pieces: the bottom, plus the steps that slide up to match it → 18 · All the up-and-down pieces → 14 · Perimeter → 32","more":"What is special here: Only the width and the height are given — and that is all you need. The steps slide out to make the rectangle's other two sides.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn|0"},"idea-staircase-perimeter-case1":{"id":"idea-staircase-perimeter-case1","kind":"idea","src":"stop:staircase-perimeter#case1","title":"Staircase perimeters: Only the steps are marked","body":"Add the step widths: together they are as wide as the bottom. Add the step heights: together they are as tall as the left side.","more":"The method: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn|1"},"idea-staircase-perimeter-case2":{"id":"idea-staircase-perimeter-case2","kind":"idea","src":"stop:staircase-perimeter#case2","title":"Staircase perimeters: A slot in one side","body":"The slot's two walls go in and out again, so they add to the rectangle's perimeter. Its width changes nothing.","more":"The method: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"See it worked","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn|2"},"worked-staircase-perimeter-worked2":{"id":"worked-staircase-perimeter-worked2","kind":"worked","src":"stop:staircase-perimeter#worked2","title":"Worked out — Staircase perimeters: A slot in one side","body":"A 10 cm by 6 cm rectangle has a slot 3 cm wide and 2 cm deep cut into its top edge. What is the perimeter of the shape that is left, in cm?: Across pieces: top and bottom of the rectangle → 20 · Up-and-down pieces: the two sides → 12 · The slot's two walls → 4 · Perimeter → 36","more":"What is special here: The slot's two walls go in and out again, so they add to the rectangle's perimeter. Its width changes nothing.","cta":"Watch it step by step","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn|2"},"why-staircase-perimeter-why1":{"id":"why-staircase-perimeter-why1","kind":"why","src":"stop:staircase-perimeter#why1","title":"Why “Staircase perimeters” works","body":"So the steps are exactly as long as the top and right sides of the rectangle drawn round the shape. The perimeter of the staircase is the perimeter of that rectangle: 2 × (width + height). You never needed to know the size of a single step — which is why the question only told you two lengths.","more":"The trick: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn"},"why-staircase-perimeter-why2":{"id":"why-staircase-perimeter-why2","kind":"why","src":"stop:staircase-perimeter#why2","title":"Why “Staircase perimeters” works","body":"Careful with a slot cut into the middle of a side. Its two walls go down into the shape and back up, and they cannot slide out to the edge — nothing is there to fill. So a slot adds both of its walls to the rectangle's perimeter. Its width does not matter at all: the bottom of the slot simply replaces the piece of edge that was cut away.","more":"The trick: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn"},"algebra-staircase-perimeter-alg":{"id":"algebra-staircase-perimeter-alg","kind":"algebra","src":"stop:staircase-perimeter#alg","title":"The algebra behind “Staircase perimeters”","body":"staircase: P = 2(W + H);  with a slot d deep: P = 2(W + H) + 2d","more":"In words: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"See why","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|learn"},"moment-staircase-perimeter-beat3":{"id":"moment-staircase-perimeter-beat3","kind":"moment","src":"story:staircase-perimeter#beat3","badge":{"id":"story","label":"A story"},"title":"The garden steps — on the notepad","body":"Dax: And the little up-pieces slide across to match the left side. 7 × 2 = 14","more":"The trick in the story: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|story|3"},"moral-staircase-perimeter-beat5":{"id":"moral-staircase-perimeter-beat5","kind":"moral","src":"story:staircase-perimeter#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The garden steps”","body":"Thirty-two metres of edging — and I never measured a single step.","more":"The trick in the story: Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's.","cta":"Read the story","where":"The Figure Fair · Level 5","level":5,"route":"#/stop/staircase-perimeter|story|5"},"try-staircase-perimeter-L5":{"id":"try-staircase-perimeter-L5","kind":"try","level":5,"src":"try:staircase-perimeter@5/1#0","title":"Staircase perimeters — your turn","where":"The Figure Fair · Level 5","route":"#/stop/staircase-perimeter|drill","cta":"Practise this stop","play":{"q":"A staircase shape with 3 steps is 10 cm wide and 10 cm tall. What is its perimeter, in cm?","opts":["40","20","41"],"after":"Push the steps out to the corner: the across pieces add up to the width and the up pieces to the height, so the perimeter is the rectangle's."}},"word-angles-on-a-line":{"id":"word-angles-on-a-line","kind":"word","src":"dictionary:angles on a line#def","title":"angles on a line","body":"Turns that sit side by side on one straight line; together they make 180°. For example: 70° and 110°.","more":"Taught at: Angles on a line and round a point.","where":"Shape City","route":"#/lib/dictionary|angles on a line","cta":"angles on a line in the Dictionary","level":5},"wordq-angles-on-a-line":{"id":"wordq-angles-on-a-line","kind":"wordq","src":"dictionary:angles on a line#ex","title":"Which maths word?","route":"#/lib/dictionary|angles on a line","cta":"Look it up","play":{"q":"Which word is this an example of? “70° and 110°.”","opts":["angles on a line","scale","composite number"],"after":"angles on a line: Turns that sit side by side on one straight line; together they make 180°."},"level":5},"word-angles-round-a-point":{"id":"word-angles-round-a-point","kind":"word","src":"dictionary:angles round a point#def","title":"angles round a point","body":"Turns that fill the whole way round one point; together they make 360°. For example: 90° + 120° + 150° = 360°.","more":"Taught at: Angles on a line and round a point.","where":"Shape City","route":"#/lib/dictionary|angles round a point","cta":"angles round a point in the Dictionary","level":5},"wordq-angles-round-a-point":{"id":"wordq-angles-round-a-point","kind":"wordq","src":"dictionary:angles round a point#ex","title":"Which maths word?","route":"#/lib/dictionary|angles round a point","cta":"Look it up","play":{"q":"Which word is this an example of? “90° + 120° + 150° = 360°.”","opts":["angles round a point","divisible","tenth"],"after":"angles round a point: Turns that fill the whole way round one point; together they make 360°."},"level":5},"word-average":{"id":"word-average","kind":"word","src":"dictionary:average#def","title":"average","body":"One number that stands for a whole list — the mean, the median or the mode. For example: For 4, 6, 6, 8 all three give 6.","more":"Taught at: The mean: fair shares.","where":"The Data Carnival","route":"#/lib/dictionary|average","cta":"average in the Dictionary","level":5},"wordq-average":{"id":"wordq-average","kind":"wordq","src":"dictionary:average#ex","title":"Which maths word?","route":"#/lib/dictionary|average","cta":"Look it up","play":{"q":"Which word is this an example of? “For 4, 6, 6, 8 all three give 6.”","opts":["average","protractor","equivalent fractions"],"after":"average: One number that stands for a whole list — the mean, the median or the mode."},"level":5},"word-base":{"id":"word-base","kind":"word","src":"dictionary:base#def","title":"base","body":"The number being multiplied in a power (the 2 in 2⁵) — or the side a shape stands on. For example: In 10³ it is the 10; in a triangle it is the bottom side.","more":"Taught at: Powers: the little number · Triangles and parallelograms.","where":"The Square Palace","route":"#/lib/dictionary|base","cta":"base in the Dictionary","level":5},"wordq-base":{"id":"wordq-base","kind":"wordq","src":"dictionary:base#ex","title":"Which maths word?","route":"#/lib/dictionary|base","cta":"Look it up","play":{"q":"Which word is this an example of? “In 10³ it is the 10; in a triangle it is the bottom side.”","opts":["base","angles on a line","isosceles triangle"],"after":"base: The number being multiplied in a power (the 2 in 2⁵) — or the side a shape stands on."},"level":5},"word-bidmas":{"id":"word-bidmas","kind":"word","src":"dictionary:BIDMAS#def","title":"BIDMAS","body":"A memory word for what goes first: Brackets, Indices, Division and Multiplication, Addition and Subtraction. For example: (2 + 3)² − 4 = 25 − 4 = 21.","more":"Taught at: Which sum first?.","where":"The Number Library","route":"#/lib/dictionary|BIDMAS","cta":"BIDMAS in the Dictionary","level":5},"wordq-bidmas":{"id":"wordq-bidmas","kind":"wordq","src":"dictionary:BIDMAS#ex","title":"Which maths word?","route":"#/lib/dictionary|BIDMAS","cta":"Look it up","play":{"q":"Which word is this an example of? “(2 + 3)² − 4 = 25 − 4 = 21.”","opts":["BIDMAS","pyramid","squared"],"after":"BIDMAS: A memory word for what goes first: Brackets, Indices, Division and Multiplication, Addition and Subtraction."},"level":5},"word-brackets":{"id":"word-brackets","kind":"word","src":"dictionary:brackets#def","title":"brackets","body":"The marks ( ) that mean “work this part out first”. For example: (2 + 3) × 4 = 20.","more":"Taught at: Which sum first?.","where":"The Number Library","route":"#/lib/dictionary|brackets","cta":"brackets in the Dictionary","level":5},"word-composite-number":{"id":"word-composite-number","kind":"word","src":"dictionary:composite number#def","title":"composite number","body":"A whole number with more than two factors, so it can be made by multiplying smaller whole numbers. For example: 15 = 3 × 5.","more":"Taught at: Is it prime?.","where":"The Factor Forest","route":"#/lib/dictionary|composite number","cta":"composite number in the Dictionary","level":5},"wordq-composite-number":{"id":"wordq-composite-number","kind":"wordq","src":"dictionary:composite number#ex","title":"Which maths word?","route":"#/lib/dictionary|composite number","cta":"Look it up","play":{"q":"Which word is this an example of? “15 = 3 × 5.”","opts":["composite number","Vedic maths","data"],"after":"composite number: A whole number with more than two factors, so it can be made by multiplying smaller whole numbers."},"level":5},"word-compound-shape":{"id":"word-compound-shape","kind":"word","src":"dictionary:compound shape#def","title":"compound shape","body":"A shape made by joining simpler shapes together. For example: An L-shape: 6 × 2 plus 2 × 3 = 12 + 6 = 18 squares.","more":"Taught at: Area of an L-shape.","where":"The Clock Tower","route":"#/lib/dictionary|compound shape","cta":"compound shape in the Dictionary","level":5},"wordq-compound-shape":{"id":"wordq-compound-shape","kind":"wordq","src":"dictionary:compound shape#ex","title":"Which maths word?","route":"#/lib/dictionary|compound shape","cta":"Look it up","play":{"q":"Which word is this an example of? “An L-shape: 6 × 2 plus 2 × 3 = 12 + 6 = 18 squares.”","opts":["compound shape","simplify","subtraction"],"after":"compound shape: A shape made by joining simpler shapes together."},"level":5},"word-function-machine":{"id":"word-function-machine","kind":"word","src":"dictionary:function machine#def","title":"function machine","body":"A box that takes a number in, does something to it, and sends the result out. For example: In 5 → × 2 → + 3 → out 13.","more":"Taught at: Working backwards.","where":"The Data Carnival","route":"#/lib/dictionary|function machine","cta":"function machine in the Dictionary","level":5},"wordq-function-machine":{"id":"wordq-function-machine","kind":"wordq","src":"dictionary:function machine#ex","title":"Which maths word?","route":"#/lib/dictionary|function machine","cta":"Look it up","play":{"q":"Which word is this an example of? “In 5 → × 2 → + 3 → out 13.”","opts":["function machine","unlikely","times table"],"after":"function machine: A box that takes a number in, does something to it, and sends the result out."},"level":5},"word-index":{"id":"word-index","kind":"word","src":"dictionary:index#def","title":"index","body":"The small raised number that says how many times the base is multiplied by itself. Plural: indices. For example: In 2⁵ it is the 5: 2 × 2 × 2 × 2 × 2 = 32.","more":"Taught at: Powers: the little number.","where":"The Square Palace","route":"#/lib/dictionary|index","cta":"index in the Dictionary","level":5},"wordq-index":{"id":"wordq-index","kind":"wordq","src":"dictionary:index#ex","title":"Which maths word?","route":"#/lib/dictionary|index","cta":"Look it up","play":{"q":"Which word is this an example of? “In 2⁵ it is the 5: 2 × 2 × 2 × 2 × 2 = 32.”","opts":["index","polygon","difference of two squares"],"after":"index: The small raised number that says how many times the base is multiplied by itself. Plural: indices."},"level":5},"word-interest":{"id":"word-interest","kind":"word","src":"dictionary:interest#def","title":"interest","body":"Extra money paid for borrowing, or earned for saving — usually a percentage each year. For example: 5% a year on £200 is £10 a year.","more":"Taught at: Percentages of an amount.","where":"The Decimal Dock","route":"#/lib/dictionary|interest","cta":"interest in the Dictionary","level":5},"wordq-interest":{"id":"wordq-interest","kind":"wordq","src":"dictionary:interest#ex","title":"Which maths word?","route":"#/lib/dictionary|interest","cta":"Look it up","play":{"q":"Which word is this an example of? “5% a year on £200 is £10 a year.”","opts":["interest","double","pi"],"after":"interest: Extra money paid for borrowing, or earned for saving — usually a percentage each year."},"level":5},"word-long-multiplication":{"id":"word-long-multiplication","kind":"word","src":"dictionary:long multiplication#def","title":"long multiplication","body":"A written method: multiply by each digit of the second number in turn, then add the rows. For example: 23 × 14 = 23 × 4 + 23 × 10 = 92 + 230 = 322.","more":"Taught at: Long multiplication.","where":"The Number Library","route":"#/lib/dictionary|long multiplication","cta":"long multiplication in the Dictionary","level":5},"wordq-long-multiplication":{"id":"wordq-long-multiplication","kind":"wordq","src":"dictionary:long multiplication#ex","title":"Which maths word?","route":"#/lib/dictionary|long multiplication","cta":"Look it up","play":{"q":"Which word is this an example of? “23 × 14 = 23 × 4 + 23 × 10 = 92 + 230 = 322.”","opts":["long multiplication","scalene triangle","vertex"],"after":"long multiplication: A written method: multiply by each digit of the second number in turn, then add the rows."},"level":5},"word-mean":{"id":"word-mean","kind":"word","src":"dictionary:mean#def","title":"mean","body":"The fair-share average: add up all the values, then share the total equally between them. For example: 3, 5 and 10: 18 ÷ 3 = 6.","more":"Taught at: The mean: fair shares.","where":"The Data Carnival","route":"#/lib/dictionary|mean","cta":"mean in the Dictionary","level":5},"wordq-mean":{"id":"wordq-mean","kind":"wordq","src":"dictionary:mean#ex","title":"Which maths word?","route":"#/lib/dictionary|mean","cta":"Look it up","play":{"q":"Which word is this an example of? “3, 5 and 10: 18 ÷ 3 = 6.”","opts":["mean","decimal place","sample space"],"after":"mean: The fair-share average: add up all the values, then share the total equally between them."},"level":5},"word-order-of-operations":{"id":"word-order-of-operations","kind":"word","src":"dictionary:order of operations#def","title":"order of operations","body":"The agreed order for working out a calculation: brackets, then powers, then × and ÷, then + and −. For example: 2 + 3 × 4 = 14, not 20.","more":"Taught at: Which sum first?.","where":"The Number Library","route":"#/lib/dictionary|order of operations","cta":"order of operations in the Dictionary","level":5},"wordq-order-of-operations":{"id":"wordq-order-of-operations","kind":"wordq","src":"dictionary:order of operations#ex","title":"Which maths word?","route":"#/lib/dictionary|order of operations","cta":"Look it up","play":{"q":"Which word is this an example of? “2 + 3 × 4 = 14, not 20.”","opts":["order of operations","exterior angle","decimal"],"after":"order of operations: The agreed order for working out a calculation: brackets, then powers, then × and ÷, then + and −."},"level":5},"word-outlier":{"id":"word-outlier","kind":"word","src":"dictionary:outlier#def","title":"outlier","body":"A value far away from all the others. For example: In 5, 6, 7, 6, 42 it is the 42.","more":"Taught at: The range: how spread out?.","where":"The Data Carnival","route":"#/lib/dictionary|outlier","cta":"outlier in the Dictionary","level":5},"wordq-outlier":{"id":"wordq-outlier","kind":"wordq","src":"dictionary:outlier#ex","title":"Which maths word?","route":"#/lib/dictionary|outlier","cta":"Look it up","play":{"q":"Which word is this an example of? “In 5, 6, 7, 6, 42 it is the 42.”","opts":["outlier","Roman numerals","cubic centimetre"],"after":"outlier: A value far away from all the others."},"level":5},"word-per-cent":{"id":"word-per-cent","kind":"word","src":"dictionary:per cent#def","title":"per cent","body":"Out of every hundred. Sign: %. For example: 25% means 25 out of every 100 — the same as 1/4.","more":"Taught at: Fractions, decimals, per cents.","where":"The Decimal Dock","route":"#/lib/dictionary|per cent","cta":"per cent in the Dictionary","level":5},"word-power":{"id":"word-power","kind":"word","src":"dictionary:power#def","title":"power","body":"A number multiplied by itself a given number of times, like 3⁴. For example: 3⁴ = 3 × 3 × 3 × 3 = 81.","more":"Taught at: Powers: the little number.","where":"The Square Palace","route":"#/lib/dictionary|power","cta":"power in the Dictionary","level":5},"wordq-power":{"id":"wordq-power","kind":"wordq","src":"dictionary:power#ex","title":"Which maths word?","route":"#/lib/dictionary|power","cta":"Look it up","play":{"q":"Which word is this an example of? “3⁴ = 3 × 3 × 3 × 3 = 81.”","opts":["power","tessellation","Pythagoras’ theorem"],"after":"power: A number multiplied by itself a given number of times, like 3⁴."},"level":5},"word-prime-number":{"id":"word-prime-number","kind":"word","src":"dictionary:prime number#def","title":"prime number","body":"A whole number greater than 1 that only 1 and itself divide exactly. For example: 13: only 1 × 13 makes it.","more":"Taught at: Is it prime?.","where":"The Factor Forest","route":"#/lib/dictionary|prime number","cta":"prime number in the Dictionary","level":5},"wordq-prime-number":{"id":"wordq-prime-number","kind":"wordq","src":"dictionary:prime number#ex","title":"Which maths word?","route":"#/lib/dictionary|prime number","cta":"Look it up","play":{"q":"Which word is this an example of? “13: only 1 × 13 makes it.”","opts":["prime number","expression","nth term"],"after":"prime number: A whole number greater than 1 that only 1 and itself divide exactly."},"level":5},"word-product":{"id":"word-product","kind":"word","src":"dictionary:product#def","title":"product","body":"The answer when numbers are multiplied together. For example: For 6 and 7 it is 42.","more":"Taught at: Long multiplication.","where":"The Number Library","route":"#/lib/dictionary|product","cta":"product in the Dictionary","level":5},"wordq-product":{"id":"wordq-product","kind":"wordq","src":"dictionary:product#ex","title":"Which maths word?","route":"#/lib/dictionary|product","cta":"Look it up","play":{"q":"Which word is this an example of? “For 6 and 7 it is 42.”","opts":["product","polygon","number line"],"after":"product: The answer when numbers are multiplied together."},"level":5},"word-profit":{"id":"word-profit","kind":"word","src":"dictionary:profit#def","title":"profit","body":"The money you make when you sell something for more than it cost you. For example: Buy for £6, sell for £10: £4.","more":"Taught at: Problems in steps.","where":"The Data Carnival","route":"#/lib/dictionary|profit","cta":"profit in the Dictionary","level":5},"wordq-profit":{"id":"wordq-profit","kind":"wordq","src":"dictionary:profit#ex","title":"Which maths word?","route":"#/lib/dictionary|profit","cta":"Look it up","play":{"q":"Which word is this an example of? “Buy for £6, sell for £10: £4.”","opts":["profit","decimal place","number line"],"after":"profit: The money you make when you sell something for more than it cost you."},"level":5},"word-range":{"id":"word-range","kind":"word","src":"dictionary:range#def","title":"range","body":"The biggest value take away the smallest — how spread out the data is. For example: 4, 9, 12, 20: 20 − 4 = 16.","more":"Taught at: The range: how spread out?.","where":"The Data Carnival","route":"#/lib/dictionary|range","cta":"range in the Dictionary","level":5},"wordq-range":{"id":"wordq-range","kind":"wordq","src":"dictionary:range#ex","title":"Which maths word?","route":"#/lib/dictionary|range","cta":"Look it up","play":{"q":"Which word is this an example of? “4, 9, 12, 20: 20 − 4 = 16.”","opts":["range","compound shape","reflex angle"],"after":"range: The biggest value take away the smallest — how spread out the data is."},"level":5},"word-recurring-decimal":{"id":"word-recurring-decimal","kind":"word","src":"dictionary:recurring decimal#def","title":"recurring decimal","body":"A decimal whose digits repeat for ever. For example: 1/3 = 0.333…","more":"Taught at: Fractions, decimals, per cents.","where":"The Decimal Dock","route":"#/lib/dictionary|recurring decimal","cta":"recurring decimal in the Dictionary","level":5},"wordq-recurring-decimal":{"id":"wordq-recurring-decimal","kind":"wordq","src":"dictionary:recurring decimal#ex","title":"Which maths word?","route":"#/lib/dictionary|recurring decimal","cta":"Look it up","play":{"q":"Which word is this an example of? “1/3 = 0.333…”","opts":["recurring decimal","million","formula"],"after":"recurring decimal: A decimal whose digits repeat for ever."},"level":5},"word-square-centimetre":{"id":"word-square-centimetre","kind":"word","src":"dictionary:square centimetre#def","title":"square centimetre","body":"The area of a square 1 cm by 1 cm. Written cm². For example: A 3 cm by 2 cm rectangle covers 6 cm².","more":"Taught at: Area of a rectangle.","where":"The Clock Tower","route":"#/lib/dictionary|square centimetre","cta":"square centimetre in the Dictionary","level":5},"wordq-square-centimetre":{"id":"wordq-square-centimetre","kind":"wordq","src":"dictionary:square centimetre#ex","title":"Which maths word?","route":"#/lib/dictionary|square centimetre","cta":"Look it up","play":{"q":"Which word is this an example of? “A 3 cm by 2 cm rectangle covers 6 cm².”","opts":["square centimetre","unit fraction","term"],"after":"square centimetre: The area of a square 1 cm by 1 cm. Written cm²."},"level":5},"word-square-number":{"id":"word-square-number","kind":"word","src":"dictionary:square number#def","title":"square number","body":"What you get when a whole number is multiplied by itself — that many dots make a perfect square. For example: 49 = 7 × 7.","more":"Taught at: What a square number is · Every square to 20.","where":"The Square Palace","route":"#/lib/dictionary|square number","cta":"square number in the Dictionary","level":5},"wordq-square-number":{"id":"wordq-square-number","kind":"wordq","src":"dictionary:square number#ex","title":"Which maths word?","route":"#/lib/dictionary|square number","cta":"Look it up","play":{"q":"Which word is this an example of? “49 = 7 × 7.”","opts":["square number","working backwards","equivalent fractions"],"after":"square number: What you get when a whole number is multiplied by itself — that many dots make a perfect square."},"level":5},"word-squared":{"id":"word-squared","kind":"word","src":"dictionary:squared#def","title":"squared","body":"Multiplied by itself, and written with a small raised 2. For example: 5² = 5 × 5 = 25.","more":"Taught at: What a square number is · Powers: the little number.","where":"The Square Palace","route":"#/lib/dictionary|squared","cta":"squared in the Dictionary","level":5},"wordq-squared":{"id":"wordq-squared","kind":"wordq","src":"dictionary:squared#ex","title":"Which maths word?","route":"#/lib/dictionary|squared","cta":"Look it up","play":{"q":"Which word is this an example of? “5² = 5 × 5 = 25.”","opts":["squared","digit root","analogue clock"],"after":"squared: Multiplied by itself, and written with a small raised 2."},"level":5},"word-sutra":{"id":"word-sutra","kind":"word","src":"dictionary:sutra#def","title":"sutra","body":"A short saying that carries a whole method, like “by one more than the one before”. For example: That one squares 35: 3 × 4 = 12, then 25 → 1,225.","more":"Taught at: Squaring numbers that end in 5 · Vertically and crosswise.","where":"The Sutra Observatory","route":"#/lib/dictionary|sutra","cta":"sutra in the Dictionary","level":5},"wordq-sutra":{"id":"wordq-sutra","kind":"wordq","src":"dictionary:sutra#ex","title":"Which maths word?","route":"#/lib/dictionary|sutra","cta":"Look it up","play":{"q":"Which word is this an example of? “That one squares 35: 3 × 4 = 12, then 25 → 1,225.”","opts":["sutra","pie chart","formula"],"after":"sutra: A short saying that carries a whole method, like “by one more than the one before”."},"level":5},"word-tessellation":{"id":"word-tessellation","kind":"word","src":"dictionary:tessellation#def","title":"tessellation","body":"A pattern of shapes that fit together with no gaps and no overlaps. For example: Squares on a chessboard: 4 meet at each corner, 4 × 90° = 360°.","more":"Taught at: Angles on a line and round a point.","where":"Shape City","route":"#/lib/dictionary|tessellation","cta":"tessellation in the Dictionary","level":5},"wordq-tessellation":{"id":"wordq-tessellation","kind":"wordq","src":"dictionary:tessellation#ex","title":"Which maths word?","route":"#/lib/dictionary|tessellation","cta":"Look it up","play":{"q":"Which word is this an example of? “Squares on a chessboard: 4 meet at each corner, 4 × 90° = 360°.”","opts":["tessellation","commutative","rounding"],"after":"tessellation: A pattern of shapes that fit together with no gaps and no overlaps."},"level":5},"word-vedic-maths":{"id":"word-vedic-maths","kind":"word","src":"dictionary:Vedic maths#def","title":"Vedic maths","body":"A set of mental shortcuts with Sanskrit names, set out by Bharati Krishna Tirtha in a book published in 1965. Scholars who have looked have not found them in the Vedas. For example: 98 × 97: 2 short and 3 short of 100 → 95 | 06 = 9,506.","more":"Taught at: Near a hundred · Squaring numbers that end in 5.","where":"The Sutra Observatory","route":"#/lib/dictionary|Vedic maths","cta":"Vedic maths in the Dictionary","source":"Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","level":5},"wordq-vedic-maths":{"id":"wordq-vedic-maths","kind":"wordq","src":"dictionary:Vedic maths#ex","title":"Which maths word?","route":"#/lib/dictionary|Vedic maths","cta":"Look it up","play":{"q":"Which word is this an example of? “98 × 97: 2 short and 3 short of 100 → 95 | 06 = 9,506.”","opts":["Vedic maths","right angle","rhombus"],"after":"Vedic maths: A set of mental shortcuts with Sanskrit names, set out by Bharati Krishna Tirtha in a book published in 1965. Scholars who have looked have not found them in the Vedas."},"level":5},"word-vertically-opposite-angles":{"id":"word-vertically-opposite-angles","kind":"word","src":"dictionary:vertically opposite angles#def","title":"vertically opposite angles","body":"The equal pair of turns facing each other across the point where two straight lines cross. For example: If one is 40°, the one across is 40° too.","more":"Taught at: Angles on a line and round a point.","where":"Shape City","route":"#/lib/dictionary|vertically opposite angles","cta":"vertically opposite angles in the Dictionary","level":5},"wordq-vertically-opposite-angles":{"id":"wordq-vertically-opposite-angles","kind":"wordq","src":"dictionary:vertically opposite angles#ex","title":"Which maths word?","route":"#/lib/dictionary|vertically opposite angles","cta":"Look it up","play":{"q":"Which word is this an example of? “If one is 40°, the one across is 40° too.”","opts":["vertically opposite angles","hundredth","recurring decimal"],"after":"vertically opposite angles: The equal pair of turns facing each other across the point where two straight lines cross."},"level":5},"formula-area-rectangle":{"id":"formula-area-rectangle","kind":"formula","src":"formula:area-rectangle","title":"Area of a rectangle","body":"A = l × w. Each row holds l squares, and there are w rows.","more":"Taught at: Area of a rectangle.","where":"The Clock Tower","route":"#/lib/formulas|area-rectangle","cta":"Area of a rectangle in the Formula Book","play":{"q":"Area of a rectangle: A rectangle 8 cm by 5 cm.","opts":["40","41","39"],"after":"A = 8 × 5 · = 40 cm²"},"level":5},"formula-why-area-rectangle-0":{"id":"formula-why-area-rectangle-0","kind":"formula-why","src":"formula:area-rectangle#why0","title":"Why A = l × w","body":"Cover the rectangle in centimetre squares. Each row along the length holds l squares, and there are w rows the same.","more":"The card: Area of a rectangle — Each row holds l squares, and there are w rows.","route":"#/lib/formulas|area-rectangle","cta":"Area of a rectangle in the Formula Book","level":5},"formula-why-area-rectangle-1":{"id":"formula-why-area-rectangle-1","kind":"formula-why","src":"formula:area-rectangle#why1","title":"Why A = l × w","body":"Equal rows are exactly what multiplication counts, so the area is l × w square units — no counting one by one. That is why area is measured in cm²: it is a count of squares.","more":"The card: Area of a rectangle — Each row holds l squares, and there are w rows.","route":"#/lib/formulas|area-rectangle","cta":"Area of a rectangle in the Formula Book","level":5},"formula-story-area-rectangle":{"id":"formula-story-area-rectangle","kind":"formula-story","src":"formula:area-rectangle#story","badge":{"id":"story","label":"A story"},"title":"The kitchen floor","body":"Dax is tiling a kitchen floor. It is 6 tiles long and 4 tiles wide. How many tiles does he need? — with Mira and Dax.","art":"art/s-kitchen.webp","route":"#/lib/formulas|area-rectangle","cta":"Area of a rectangle in the Formula Book","level":5},"formula-try-area-rectangle":{"id":"formula-try-area-rectangle","kind":"formula-try","src":"formula:area-rectangle#gen0","title":"Area of a rectangle — your turn","route":"#/lib/formulas|area-rectangle","cta":"Area of a rectangle in the Formula Book","play":{"q":"Area of a rectangle 10 cm by 3 cm (in cm²) = ?","opts":["30","31","29"],"after":"A = l × w"},"level":5},"formula-area-square":{"id":"formula-area-square","kind":"formula","src":"formula:area-square","title":"Area of a square","body":"A = s × s = s². s rows of s squares: s², “s squared”.","more":"Taught at: Area of a rectangle · What a square number is.","where":"The Clock Tower","route":"#/lib/formulas|area-square","cta":"Area of a square in the Formula Book","play":{"q":"Area of a square: A square with 9 cm sides.","opts":["81","82","80"],"after":"A = 9 × 9 · = 81 cm²"},"level":5},"formula-why-area-square-1":{"id":"formula-why-area-square-1","kind":"formula-why","src":"formula:area-square#why1","title":"Why A = s × s = s²","body":"That is why s × s is called “s squared”: it is how many unit squares tile a square with side s. 7² = 49 means a 7 by 7 square holds 49 little squares.","more":"The card: Area of a square — s rows of s squares: s², “s squared”.","route":"#/lib/formulas|area-square","cta":"Area of a square in the Formula Book","level":5},"formula-try-area-square":{"id":"formula-try-area-square","kind":"formula-try","src":"formula:area-square#gen0","title":"Area of a square — your turn","route":"#/lib/formulas|area-square","cta":"Area of a square in the Formula Book","play":{"q":"Area of a square with 20 cm sides (in cm²) = ?","opts":["400","401","399"],"after":"A = s × s = s²"},"level":5},"formula-area-trapezium":{"id":"formula-area-trapezium","kind":"formula","src":"formula:area-trapezium","title":"Area of a trapezium","body":"A = ½ × (a + b) × h. Two trapeziums, one turned over, make a parallelogram with base a + b.","more":"Taught at: Triangles and parallelograms · Area of an L-shape.","where":"The Clock Tower","route":"#/lib/formulas|area-trapezium","cta":"Area of a trapezium in the Formula Book","play":{"q":"Area of a trapezium: Parallel sides 5 cm and 9 cm, height 4 cm.","opts":["28","29","27"],"after":"a + b = 5 + 9 = 14 · 14 × 4 = 56 · A = 56 ÷ 2 = 28 cm²"},"level":5},"formula-why-area-trapezium-0":{"id":"formula-why-area-trapezium-0","kind":"formula-why","src":"formula:area-trapezium#why0","title":"Why A = ½ × (a + b) × h","body":"Take two copies of the trapezium and turn one upside down. Push them together and they make a parallelogram.","more":"The card: Area of a trapezium — Two trapeziums, one turned over, make a parallelogram with base a + b.","route":"#/lib/formulas|area-trapezium","cta":"Area of a trapezium in the Formula Book","level":5},"formula-why-area-trapezium-1":{"id":"formula-why-area-trapezium-1","kind":"formula-why","src":"formula:area-trapezium#why1","title":"Why A = ½ × (a + b) × h","body":"Its base is a + b — the short side of one next to the long side of the other — and its height is h, so the pair covers (a + b) × h. One trapezium is half of the pair: A = ½ × (a + b) × h.","more":"The card: Area of a trapezium — Two trapeziums, one turned over, make a parallelogram with base a + b.","route":"#/lib/formulas|area-trapezium","cta":"Area of a trapezium in the Formula Book","level":5},"formula-story-area-trapezium":{"id":"formula-story-area-trapezium","kind":"formula-story","src":"formula:area-trapezium#story","badge":{"id":"story","label":"A story"},"title":"The stage ramp","body":"Kwame is painting the side of a stage ramp. It is 2 metres tall at one end, 4 metres at the other, and 5 metres long. — with Kwame and Dax.","art":"art/s-hall.webp","route":"#/lib/formulas|area-trapezium","cta":"Area of a trapezium in the Formula Book","level":5},"formula-try-area-trapezium":{"id":"formula-try-area-trapezium","kind":"formula-try","src":"formula:area-trapezium#gen0","title":"Area of a trapezium — your turn","route":"#/lib/formulas|area-trapezium","cta":"Area of a trapezium in the Formula Book","play":{"q":"Area of a trapezium with parallel sides 6 cm and 8 cm, height 9 cm (in cm²) = ?","opts":["63","64","62"],"after":"A = ½ × (a + b) × h"},"level":5},"formula-angles-on-a-line":{"id":"formula-angles-on-a-line","kind":"formula","src":"formula:angles-on-a-line","title":"Angles on a straight line","body":"a + b = 180°. A straight line is a half turn; the pieces share it.","more":"Taught at: Angles on a line and round a point.","where":"Shape City","route":"#/lib/formulas|angles-on-a-line","cta":"Angles on a straight line in the Formula Book","play":{"q":"Angles on a straight line: One angle on a straight line is 65°.","opts":["115","116","114"],"after":"180 − 65 = 115°"},"level":5},"formula-why-angles-on-a-line-0":{"id":"formula-why-angles-on-a-line-0","kind":"formula-why","src":"formula:angles-on-a-line#why0","title":"Why a + b = 180°","body":"A straight line is a half turn. Stand facing one way along it, turn to face the other way, and you have turned 180°.","more":"The card: Angles on a straight line — A straight line is a half turn; the pieces share it.","route":"#/lib/formulas|angles-on-a-line","cta":"Angles on a straight line in the Formula Book","level":5},"formula-why-angles-on-a-line-1":{"id":"formula-why-angles-on-a-line-1","kind":"formula-why","src":"formula:angles-on-a-line#why1","title":"Why a + b = 180°","body":"If another line splits that half turn into two angles, the two pieces still make the whole half turn between them. So angles on a straight line add to 180°, and a missing one is 180° take away the others.","more":"The card: Angles on a straight line — A straight line is a half turn; the pieces share it.","route":"#/lib/formulas|angles-on-a-line","cta":"Angles on a straight line in the Formula Book","level":5},"formula-story-angles-on-a-line":{"id":"formula-story-angles-on-a-line","kind":"formula-story","src":"formula:angles-on-a-line#story","badge":{"id":"story","label":"A story"},"title":"The leaning book","body":"On the library shelf a book has slipped. It leans at 70° to the shelf. What is the angle on its other side? — with Theo and Nova.","art":"art/s-library.webp","route":"#/lib/formulas|angles-on-a-line","cta":"Angles on a straight line in the Formula Book","level":5},"formula-try-angles-on-a-line":{"id":"formula-try-angles-on-a-line","kind":"formula-try","src":"formula:angles-on-a-line#gen0","title":"Angles on a straight line — your turn","route":"#/lib/formulas|angles-on-a-line","cta":"Angles on a straight line in the Formula Book","play":{"q":"Two angles sit on a straight line. One is 155°. The other (in °)?","opts":["25","26","24"],"after":"a + b = 180°"},"level":5},"formula-angles-round-a-point":{"id":"formula-angles-round-a-point","kind":"formula","src":"formula:angles-round-a-point","title":"Angles round a point","body":"a + b + c = 360°. However many pieces, together they are one full turn.","more":"Taught at: Angles on a line and round a point.","where":"Shape City","route":"#/lib/formulas|angles-round-a-point","cta":"Angles round a point in the Formula Book","play":{"q":"Angles round a point: Two of three angles round a point are 100° and 140°.","opts":["120","121","119"],"after":"100 + 140 = 240 · 360 − 240 = 120°"},"level":5},"formula-why-angles-round-a-point-0":{"id":"formula-why-angles-round-a-point-0","kind":"formula-why","src":"formula:angles-round-a-point#why0","title":"Why a + b + c = 360°","body":"Turn all the way round on the spot and you face the way you started: a full turn is 360°.","more":"The card: Angles round a point — However many pieces, together they are one full turn.","route":"#/lib/formulas|angles-round-a-point","cta":"Angles round a point in the Formula Book","level":5},"formula-why-angles-round-a-point-1":{"id":"formula-why-angles-round-a-point-1","kind":"formula-why","src":"formula:angles-round-a-point#why1","title":"Why a + b + c = 360°","body":"Lines coming out of one point cut that full turn into pieces. However many pieces there are, together they are still the one full turn, so they add to 360°.","more":"The card: Angles round a point — However many pieces, together they are one full turn.","route":"#/lib/formulas|angles-round-a-point","cta":"Angles round a point in the Formula Book","level":5},"formula-story-angles-round-a-point":{"id":"formula-story-angles-round-a-point","kind":"formula-story","src":"formula:angles-round-a-point#story","badge":{"id":"story","label":"A story"},"title":"The last slice","body":"Pip cuts a round pizza from the middle. His slice has a 100° angle at the centre and Ines’s has 140°. The rest is saved for later. — with Pip and Ines.","art":"art/s-kitchen.webp","route":"#/lib/formulas|angles-round-a-point","cta":"Angles round a point in the Formula Book","level":5},"formula-try-angles-round-a-point":{"id":"formula-try-angles-round-a-point","kind":"formula-try","src":"formula:angles-round-a-point#gen0","title":"Angles round a point — your turn","route":"#/lib/formulas|angles-round-a-point","cta":"Angles round a point in the Formula Book","play":{"q":"Three angles fill the space round a point. Two are 99° and 181°. The third (in °)?","opts":["80","81","79"],"after":"a + b + c = 360°"},"level":5},"formula-mean":{"id":"formula-mean","kind":"formula","src":"formula:mean","title":"The mean","body":"mean = total ÷ how many. Tall bars give to short ones until every bar is level.","more":"Taught at: The mean: fair shares.","where":"The Data Carnival","route":"#/lib/formulas|mean","cta":"The mean in the Formula Book","play":{"q":"The mean: The mean of 4, 7 and 10.","opts":["7","8","6"],"after":"4 + 7 + 10 = 21 · 21 ÷ 3 = 7"},"level":5},"formula-why-mean-0":{"id":"formula-why-mean-0","kind":"formula-why","src":"formula:mean#why0","title":"Why mean = total ÷ how many","body":"The mean asks: if everything were shared out fairly, how much would each get? Put all the values together into one pile — that is the total.","more":"The card: The mean — Tall bars give to short ones until every bar is level.","route":"#/lib/formulas|mean","cta":"The mean in the Formula Book","level":5},"formula-why-mean-1":{"id":"formula-why-mean-1","kind":"formula-why","src":"formula:mean#why1","title":"Why mean = total ÷ how many","body":"Then share the pile equally between all of them: total ÷ how many. Tall bars give some to short bars until every bar is the same height; that height is the mean.","more":"The card: The mean — Tall bars give to short ones until every bar is level.","route":"#/lib/formulas|mean","cta":"The mean in the Formula Book","level":5},"formula-story-mean":{"id":"formula-story-mean","kind":"formula-story","src":"formula:mean#story","badge":{"id":"story","label":"A story"},"title":"Sharing the sweets","body":"At the festival Nova collects 9 sweets, Suki 4 and their friend 8. They agree to share them out fairly. — with Nova and Suki.","art":"art/s-festival.webp","route":"#/lib/formulas|mean","cta":"The mean in the Formula Book","level":5},"formula-try-mean":{"id":"formula-try-mean","kind":"formula-try","src":"formula:mean#gen0","title":"The mean — your turn","route":"#/lib/formulas|mean","cta":"The mean in the Formula Book","play":{"q":"The mean of 12, 8, 7?","opts":["9","10","8"],"after":"mean = total ÷ how many"},"level":5},"formula-range":{"id":"formula-range","kind":"formula","src":"formula:range","title":"The range","body":"range = biggest − smallest. Only the two ends matter.","more":"Taught at: The range: how spread out?.","where":"The Data Carnival","route":"#/lib/formulas|range","cta":"The range in the Formula Book","play":{"q":"The range: The range of 12, 5, 19 and 8.","opts":["14","15","13"],"after":"biggest 19, smallest 5 · 19 − 5 = 14"},"level":5},"formula-why-range-0":{"id":"formula-why-range-0","kind":"formula-why","src":"formula:range#why0","title":"Why range = biggest − smallest","body":"The range tells you how spread out the data is: the distance from the smallest value to the biggest.","more":"The card: The range — Only the two ends matter.","route":"#/lib/formulas|range","cta":"The range in the Formula Book","level":5},"formula-why-range-1":{"id":"formula-why-range-1","kind":"formula-why","src":"formula:range#why1","title":"Why range = biggest − smallest","body":"Only the two ends matter, so hunt for the biggest and the smallest and take one from the other. A big range means the values are spread wide; a small one means they bunch together.","more":"The card: The range — Only the two ends matter.","route":"#/lib/formulas|range","cta":"The range in the Formula Book","level":5},"formula-story-range":{"id":"formula-story-range","kind":"formula-story","src":"formula:range#story","badge":{"id":"story","label":"A story"},"title":"The long jump","body":"Dax’s long jumps at sports day: 310 cm, 285 cm, 342 cm and 298 cm. How spread out are they? — with Dax and Suki.","art":"art/s-stadium.webp","route":"#/lib/formulas|range","cta":"The range in the Formula Book","level":5},"formula-try-range":{"id":"formula-try-range","kind":"formula-try","src":"formula:range#gen0","title":"The range — your turn","route":"#/lib/formulas|range","cta":"The range in the Formula Book","play":{"q":"The range of 23, 48, 32, 51, 55, 17, 54?","opts":["38","39","37"],"after":"range = biggest − smallest"},"level":5},"stone-vedic-origin":{"src":"journey:vedic/origin#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic|origin","cta":"Stone 1: Where the sutras come from","where":"The Vedic Maths Journey · stone 1 of 13","id":"stone-vedic-origin","kind":"stone","title":"Where the sutras come from","body":"The short Sanskrit sayings in this part of the Atlas — the sutras — were set out by Bharati Krishna Tirtha in a book called Vedic Mathematics, published in 1965, five years after he died.","level":5},"stone-vedic-origin-1":{"src":"journey:vedic/origin#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic|origin","cta":"Stone 1: Where the sutras come from","where":"The Vedic Maths Journey · stone 1 of 13","id":"stone-vedic-origin-1","kind":"stone-step","title":"Where the sutras come from (2 of 4)","body":"He said they came from the Vedas. Scholars who have looked have not found them in any Vedic text, so the honest name is: methods from a twentieth-century Indian book, with Sanskrit names.","level":5},"stone-vedic-origin-2":{"src":"journey:vedic/origin#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic|origin","cta":"Stone 1: Where the sutras come from","where":"The Vedic Maths Journey · stone 1 of 13","id":"stone-vedic-origin-2","kind":"stone-step","title":"Where the sutras come from (3 of 4)","body":"That takes nothing away from them. They are quick, they are clever, and every one of them works for a reason you can check — ordinary algebra. That reason is what each stop here shows you.","level":5},"stone-vedic-origin-3":{"src":"journey:vedic/origin#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965). S. G. Dani, \"Myths and reality: on 'Vedic mathematics'\", Frontline, 1993.","route":"#/lib/vedic|origin","cta":"Stone 1: Where the sutras come from","where":"The Vedic Maths Journey · stone 1 of 13","id":"stone-vedic-origin-3","kind":"stone-step","title":"Where the sutras come from (4 of 4)","body":"The book gives sixteen short sutras, and some shorter sub-sutras that go with them. This path walks through the ones you can use with a pencil — or with no pencil at all. On every stone you will see the method, then the algebra that makes it work, then try it yourself.","level":5},"stone-vedic-ekadhika":{"src":"journey:vedic/ekadhika#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|ekadhika","cta":"Stone 2: One more than the one before","where":"The Vedic Maths Journey · stone 2 of 13","id":"stone-vedic-ekadhika","kind":"stone","title":"One more than the one before — Ekādhikena Pūrvena","body":"To square a number that ends in 5, look at the digits in front of the 5. Multiply them by one more than themselves. Then write 25 on the end.","level":5},"stone-vedic-ekadhika-1":{"src":"journey:vedic/ekadhika#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|ekadhika","cta":"Stone 2: One more than the one before","where":"The Vedic Maths Journey · stone 2 of 13","id":"stone-vedic-ekadhika-1","kind":"stone-step","title":"One more than the one before (2 of 4)","body":"65²: in front of the 5 is 6. One more than 6 is 7, and 6 × 7 = 42. Write 25 after it: 4225.","level":5},"stone-vedic-ekadhika-2":{"src":"journey:vedic/ekadhika#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|ekadhika","cta":"Stone 2: One more than the one before","where":"The Vedic Maths Journey · stone 2 of 13","id":"stone-vedic-ekadhika-2","kind":"stone-step","title":"One more than the one before (3 of 4)","body":"Why it works: a number ending in 5 is 10n + 5. Squared, that is 100n² + 100n + 25, which is 100 × n(n + 1) + 25. The n(n + 1) is the \"one more than the one before\"; the 25 is 5 × 5.","level":5},"stone-vedic-ekadhika-3":{"src":"journey:vedic/ekadhika#3","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|ekadhika","cta":"Stone 2: One more than the one before","where":"The Vedic Maths Journey · stone 2 of 13","id":"stone-vedic-ekadhika-3","kind":"stone-step","title":"One more than the one before (4 of 4)","body":"The same sutra makes the digits of 1 ÷ 19. The digit before the 9 in 19 is 1, and one more than it is 2 — so start from the right with 1, and keep doubling to the left, carrying as you go. You get all eighteen digits that repeat: 0.052631578947368421… (on the Stretch level you try this too).","level":5},"stone-try-vedic-ekadhika":{"src":"journey:vedic/ekadhika#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|ekadhika","cta":"Stone 2: One more than the one before","where":"The Vedic Maths Journey · stone 2 of 13","id":"stone-try-vedic-ekadhika","kind":"stone-try","title":"One more than the one before — try it","play":{"q":"95² = ?","opts":["9025","90","9026"],"after":"Squares ending in 5"},"level":5}};
